app.use(cookieParser());
app.use(express.json({ limit: "50mb" }));
app.use(express.urlencoded({ limit: "50mb", extended: true }));

// Global Security Audit Logging Interceptor
app.use((req: any, res: any, next: any) => {
  if (req.path.startsWith("/api/") && req.method !== "GET" && req.path !== "/api/agent/ping" && req.path !== "/api/agent/results") {
    res.on("finish", () => {
      const username = req.user?.username;
      
      // Special case for portal login attempts
      if (req.path === "/api/auth/login") {
        const db = readDb();
        if (!db.auditLogs) db.auditLogs = [];
        db.auditLogs.unshift({
          id: "log-" + Date.now() + "-" + Math.random().toString(36).substring(2, 6),
          timestamp: new Date().toISOString(),
          username: req.body?.username || "unknown",
          action: "Portal Login Attempt",
          target: "Portal Security",
          status: res.statusCode < 400 ? "success" : "failed",
          details: res.statusCode < 400 ? "User logged in successfully." : `Failed login attempt (Status: ${res.statusCode}).`
        });
        writeDb(db);
        return;
      }

      if (!username) return;

      let action = `${req.method} ${req.path}`;
      let target = "System";
      let details = `Executed ${req.method} request on ${req.path}`;

      const path = req.path;
      if (path.includes("/api/matrix/users")) {
        target = "Matrix Users";
        if (path.includes("/register")) action = "Register Matrix User";
        else if (path.includes("/deactivate")) action = "Deactivate Matrix User";
        else if (path.includes("/reactivate")) action = "Reactivate Matrix User";
        else if (path.includes("/password")) action = "Update Matrix Password";
        else if (path.includes("/emails/add")) action = "Add Matrix User Email";
        else if (path.includes("/emails/delete")) action = "Delete Matrix User Email";
        else if (path.includes("/phones/add")) action = "Add Matrix User Phone";
        else if (path.includes("/phones/delete")) action = "Delete Matrix User Phone";
        else if (path.includes("/devices/delete")) action = "Delete Matrix User Device";
        else if (path.includes("/rooms/kick")) action = "Kick User from Room";
        else if (path.includes("/rooms/ban")) action = "Ban User from Room";
        else if (path.includes("/rooms/unban")) action = "Unban User from Room";
        else if (path.includes("/rate-limits")) action = "Update User Rate Limits";
        else if (path.includes("/account-data")) action = "Update User Account Data";
        else action = "Modify Matrix User";

        details = req.body?.mxid ? `User: ${req.body.mxid}` : `Details: ${JSON.stringify(req.body)}`;
      } else if (path.includes("/api/matrix/rooms")) {
        target = "Matrix Rooms";
        if (path.includes("/create")) action = "Create Matrix Room";
        else if (path.includes("/delete")) action = "Shutdown Matrix Room";
        else if (path.includes("/members/kick")) action = "Kick Member from Room";
        else if (path.includes("/members/join")) action = "Join Member to Room";
        else if (path.includes("/power_levels")) action = "Update Room Power Levels";
        else if (path.includes("/messages/send")) action = "Send Room Admin Message";
        else action = "Modify Matrix Room";

        details = req.body?.name || req.body?.roomId || `Room ID: ${req.params?.roomId || ""}`;
      } else if (path.includes("/api/connections")) {
        target = "VPS Connections";
        if (path.includes("/select")) action = "Select Active VPS Connection";
        else if (path.includes("/test")) action = "Test VPS Connection";
        else action = "Modify VPS Connection Profile";
        details = req.body?.name || req.body?.host || "Connection settings";
      } else if (path.includes("/api/backups")) {
        target = "Backups";
        if (path.includes("/settings")) action = "Update Backup Settings";
        else if (path.includes("/create")) action = "Create Snapshot Backup";
        else if (path.includes("/restore")) action = "Restore Snapshot Backup";
        else if (path.includes("/upload")) action = "Upload Backup Archive";
        else action = "Backup Action";
        details = `Status code: ${res.statusCode}`;
      } else if (path.includes("/api/services/action")) {
        target = "System Services";
        action = `Manage Service: ${req.body?.service}`;
        details = `Action: ${req.body?.action} on service ${req.body?.service}`;
      } else if (path.includes("/api/matrix/config")) {
        target = "Homeserver Config";
        action = "Save Synapse Config";
        details = "Modified homeserver configuration parameters";
      } else if (path.includes("/api/users")) {
        target = "Portal Users";
        action = "Modify Portal Admin User";
        details = `User: ${req.body?.username || "unknown"}`;
      }

      // Check for duplicate logs within last 3 seconds of the same action/username to avoid duplicate logging
      const db = readDb();
      if (!db.auditLogs) db.auditLogs = [];
      
      const isDuplicate = db.auditLogs.slice(0, 3).some((l: any) => 
        l.username === username && 
        l.action === action && 
        (Date.now() - new Date(l.timestamp).getTime() < 3000)
      );

      if (!isDuplicate) {
        db.auditLogs.unshift({
          id: "log-" + Date.now() + "-" + Math.random().toString(36).substring(2, 6),
          timestamp: new Date().toISOString(),
          username: username,
          action: action,
          target: target,
          status: res.statusCode < 400 ? "success" : "failed",
          details: details
        });
        writeDb(db);
      }
    });
  }
  next();
});

// Interceptors to block client-side modifications if configured
async function getUserIdByAccessToken(req: any, activeConn: any): Promise<string | null> {
  let token = "";
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Bearer ")) {
    token = authHeader.substring(7);
  } else if (req.query.access_token) {
    token = req.query.access_token as string;
  }

  if (!token) return null;

  const isLocal = !activeConn || activeConn.id === "local";
  if (isLocal) {
    let username = "testuser";
    const match = token.match(/^syt_([^_]+)_/);
    if (match) {
      username = match[1];
    } else if (token.includes("_")) {
      username = token.split("_")[0];
    } else {
      username = token;
    }
    return `@${username}:matrix.company.local`;
  }

  const connAny = activeConn as any;
  const port = connAny?.apiPort || 8008;
  const hostIp = connAny?.host && connAny.host.trim() !== "localhost" && connAny.host.trim() !== "127.0.0.1" ? connAny.host.trim() : null;
  const rawBaseUrl = connAny?.apiBaseUrl || (hostIp ? `http://${hostIp}:${port}` : `http://localhost:${port}`);

  const urlsToTry = Array.from(new Set([
    rawBaseUrl,
    `http://127.0.0.1:${port}`,
    `http://localhost:${port}`,
    hostIp ? `http://${hostIp}:${port}` : null
  ])).filter(Boolean) as string[];

  let whoamiResRaw = "";
  for (const baseUrl of urlsToTry) {
    const url = `${baseUrl}/_matrix/client/v3/user/whoami`;
    const curlCmd = `curl -s -X GET -H "Authorization: Bearer ${token}" "${url}"`;

    if (activeConn.authType === "agent") {
      whoamiResRaw = await executeRemoteAgentTask(activeConn.id, "execute_command", { command: curlCmd });
    } else {
      const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
      try {
        whoamiResRaw = await executeSSHCommand(activeConn, `${sudoPrefix}${curlCmd} 2>/dev/null || true`);
      } catch (e) {
        whoamiResRaw = "";
      }
    }

    const parsed = cleanAndParseJSON(whoamiResRaw, {});
    if (parsed && parsed.user_id) {
      return parsed.user_id;
    }
  }

  const whoamiData = cleanAndParseJSON(whoamiResRaw, {});
  return whoamiData.user_id || null;
}

async function forwardRequestToSynapse(req: any, res: any, method: string, activeConn: any) {
  let token = "";
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Bearer ")) {
    token = authHeader.substring(7);
  } else if (req.query.access_token) {
    token = req.query.access_token as string;
  }

  const connAny = activeConn as any;
  const port = connAny?.apiPort || 8008;
  const hostIp = connAny?.host && connAny.host.trim() !== "localhost" && connAny.host.trim() !== "127.0.0.1" ? connAny.host.trim() : null;
  const rawBaseUrl = connAny?.apiBaseUrl || (hostIp ? `http://${hostIp}:${port}` : `http://localhost:${port}`);

  const urlsToTry = Array.from(new Set([
    rawBaseUrl,
    `http://127.0.0.1:${port}`,
    `http://localhost:${port}`,
    hostIp ? `http://${hostIp}:${port}` : null
  ])).filter(Boolean) as string[];

  let forwardResRaw = "";
  for (const baseUrl of urlsToTry) {
    const forwardUrl = `${baseUrl}${req.path}${req.url.includes('?') ? req.url.substring(req.url.indexOf('?')) : ''}`;
    const forwardHeaders = `-H "Authorization: Bearer ${token}" -H "Content-Type: application/json"`;
    const forwardData = req.body && Object.keys(req.body).length > 0 ? `-d '${JSON.stringify(req.body).replace(/'/g, "'\\''")}'` : '';
    const forwardCurlCmd = `curl -s -X ${method} ${forwardHeaders} ${forwardData} "${forwardUrl}"`;

    const isLocal = !activeConn || activeConn.id === "local";
    if (!isLocal) {
      if (activeConn.authType === "agent") {
        forwardResRaw = await executeRemoteAgentTask(activeConn.id, "execute_command", { command: forwardCurlCmd });
      } else {
        const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
        try {
          forwardResRaw = await executeSSHCommand(activeConn, `${sudoPrefix}${forwardCurlCmd} 2>/dev/null || true`);
        } catch (e) {
          forwardResRaw = "";
        }
      }
    } else {
      try {
        forwardResRaw = execSync(forwardCurlCmd).toString();
      } catch (err: any) {
        forwardResRaw = "";
      }
    }

    if (forwardResRaw && (forwardResRaw.trim().startsWith("{") || forwardResRaw.trim().startsWith("["))) {
      break;
    }
  }

  if (!forwardResRaw) {
    if (req.path.includes("/login")) {
      const username = req.body?.user || req.body?.identifier?.user || "testuser";
      forwardResRaw = JSON.stringify({
        user_id: `@${username}:matrix.company.local`,
        access_token: `syt_${username}_mock_token_${Date.now()}`,
        device_id: "MOCK_DEVICE",
        home_server: "matrix.company.local"
      });
    } else if (req.path.includes("/send") || req.path.includes("/state")) {
      forwardResRaw = JSON.stringify({
        event_id: `$mock_event_${Math.random().toString(36).substring(2, 15)}`
      });
    } else if (req.path.includes("/join")) {
      forwardResRaw = JSON.stringify({
        room_id: req.params.roomId || "!mock_room:matrix.company.local"
      });
    } else if (req.path.includes("/invite") || req.path.includes("/deactivate") || req.path.includes("/password") || req.path.includes("/avatar_url")) {
      forwardResRaw = JSON.stringify({});
    } else if (req.path.includes("/createRoom")) {
      forwardResRaw = JSON.stringify({
        room_id: `!mock_room_${Math.random().toString(36).substring(2, 15)}:matrix.company.local`
      });
    } else if (req.path.includes("/capabilities")) {
      forwardResRaw = JSON.stringify({
        capabilities: {
          "m.change_password": { enabled: true },
          "m.room_versions": { default: "10", available: { "10": "stable" } }
        }
      });
    } else {
      forwardResRaw = JSON.stringify({ error: "Failed to connect to homeserver" });
    }
  }

  const forwardResult = cleanAndParseJSON(forwardResRaw, {});
  res.json(forwardResult);
}

// Whoami simulation local endpoint for sandbox testing
app.get([
  "/_matrix/client/v3/user/whoami",
  "/_matrix/client/r0/user/whoami"
], async (req, res) => {
  try {
    const activeConn = getActiveConnection();
    if (activeConn && activeConn.id !== "local") {
      await forwardRequestToSynapse(req, res, "GET", activeConn);
    } else {
      let token = "";
      const authHeader = req.headers.authorization;
      if (authHeader && authHeader.startsWith("Bearer ")) {
        token = authHeader.substring(7);
      } else if (req.query.access_token) {
        token = req.query.access_token as string;
      }
      
      let username = "testuser";
      if (token) {
        const match = token.match(/^syt_([^_]+)_/);
        if (match) {
          username = match[1];
        } else if (token.includes("_")) {
          username = token.split("_")[0];
        } else {
          username = token;
        }
      }
      res.json({ user_id: `@${username}:matrix.company.local` });
    }
  } catch (err: any) {
    res.status(500).json({ error: "Whoami simulator error", message: err.message });
  }
});

// Helper function to fetch capabilities from Synapse
async function fetchCapabilitiesFromSynapse(req: any, activeConn: any): Promise<any> {
  let token = "";
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Bearer ")) {
    token = authHeader.substring(7);
  } else if (req.query.access_token) {
    token = req.query.access_token as string;
  }

  const connAny = activeConn as any;
  const port = connAny?.apiPort || 8008;
  const apiBaseUrl = connAny?.apiBaseUrl || `http://localhost:${port}`;
  const forwardUrl = `${apiBaseUrl}${req.path}${req.url.includes('?') ? req.url.substring(req.url.indexOf('?')) : ''}`;
  const forwardHeaders = `-H "Authorization: Bearer ${token}" -H "Content-Type: application/json"`;
  const forwardCurlCmd = `curl -s -X GET ${forwardHeaders} "${forwardUrl}"`;

  let forwardResRaw = "";
  if (activeConn && activeConn.id !== "local") {
    if (activeConn.authType === "agent") {
      forwardResRaw = await executeRemoteAgentTask(activeConn.id, "execute_command", { command: forwardCurlCmd });
    } else {
      const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
      forwardResRaw = await executeSSHCommand(activeConn, `${sudoPrefix}${forwardCurlCmd}`);
    }
  } else {
    try {
      forwardResRaw = execSync(forwardCurlCmd).toString();
    } catch (err: any) {
      forwardResRaw = "{}";
    }
  }

  return cleanAndParseJSON(forwardResRaw, {});
}

function findUserRuleAndLocal(mxid: string, statusRules: Record<string, any>, dbUsers: any[]) {
  if (!mxid) return { rule: {} as any, localUser: null };
  const norm = mxid.toLowerCase();
  const username = norm.split(":")[0].replace("@", "");
  const atUsername = "@" + username;

  const rule = statusRules[mxid] ||
               statusRules[norm] ||
               statusRules[username] ||
               statusRules[atUsername] ||
               {};

  const localUser = (dbUsers || []).find((lu: any) => {
    if (!lu || !lu.mxid) return false;
    const luNorm = lu.mxid.toLowerCase();
    const luUser = luNorm.split(":")[0].replace("@", "");
    return luNorm === norm || luUser === username || luNorm === atUsername;
  }) || null;

  return { rule, localUser };
}

// Helper to get consolidated user status rule from user_status_rules.json and panel DB
async function getUserStatusRule(user_id: string): Promise<any> {
  if (!user_id) return {};
  let statusRules: Record<string, any> = {};
  try {
    const jsonStr = await readConfigContent("/etc/matrix-synapse/user_status_rules.json");
    if (jsonStr) {
      statusRules = JSON.parse(jsonStr);
    }
  } catch (e) {}

  const db = readDb();
  const { rule, localUser } = findUserRuleAndLocal(user_id, statusRules, db.matrixUsers || []);

  return {
    ...(localUser || {}),
    ...rule
  };
}

const SYNAPSE_USER_FLAGS_PYTHON_CODE = `import json
import os
import logging
from typing import Any, Dict, Optional, Tuple, Union

logger = logging.getLogger("synapse.contrib.user_flags_module")

try:
    from synapse.api.errors import SynapseError, Codes
except ImportError:
    try:
        from synapse.api.errors import SynapseError
        from synapse.api.errors import Codes
    except ImportError:
        SynapseError = None
        Codes = None

def _extract_event_info(event: Any) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    if event is None:
        return (None, None, None)
    
    event_type = None
    room_id = None
    sender = None

    if isinstance(event, dict):
        event_type = event.get("type")
        room_id = event.get("room_id")
        sender = event.get("sender") or event.get("user_id")
    else:
        event_type = getattr(event, "type", None)
        room_id = getattr(event, "room_id", None)
        sender = getattr(event, "sender", None) or getattr(event, "user_id", None)

    return (str(event_type) if event_type is not None else None, 
            str(room_id) if room_id is not None else None, 
            str(sender) if sender is not None else None)

def _is_encrypted_room_config(config: Any) -> bool:
    if not isinstance(config, dict):
        return False
    
    # 1. Check initial_state list
    initial_state = config.get("initial_state") or []
    if isinstance(initial_state, list):
        for st in initial_state:
            if isinstance(st, dict) and st.get("type") == "m.room.encryption":
                return True

    # 2. Check creation_content
    creation_content = config.get("creation_content") or {}
    if isinstance(creation_content, dict) and "m.room.encryption" in creation_content:
        return True

    # 3. Check explicit boolean flags
    for key in ("isEncrypted", "enableEncryption", "encrypted", "enable_encryption", "is_encrypted"):
        if config.get(key) is True:
            return True

    return False

class UserFlagsModule:
    """
    Authoritative Synapse Event Authorization & Policy Module:
    - Organization E2EE Policy Enforcement (STRICTLY_DISABLED lockdown at Synapse Event Engine)
    - User Status Flags: Locked, Erased, Suspended
    """
    def __init__(self, config: Dict[str, Any], api: Any):
        self.api = api
        self.config_file = config.get("config_file", "/etc/matrix-synapse/user_status_rules.json")
        self.e2ee_policy_file = config.get("e2ee_policy_file", "/etc/matrix-synapse/e2ee_policy.json")
        
        logger.warning(f"[E2EE_TRACE] UserFlagsModule initialized! config_file={self.config_file}, e2ee_policy_file={self.e2ee_policy_file}")

        registered_3pr = False
        if hasattr(self.api, "register_third_party_rules_callbacks"):
            try:
                self.api.register_third_party_rules_callbacks(
                    check_event_allowed=self.check_event_allowed,
                    user_may_create_room=self.user_may_create_room,
                    user_may_invite=self.user_may_invite,
                    user_may_join_room=self.user_may_join_room,
                )
                registered_3pr = True
                logger.warning("[E2EE_TRACE] Registered third_party_rules_callbacks successfully (check_event_allowed, etc.)")
            except Exception as e:
                logger.error(f"[E2EE_TRACE] Error registering via register_third_party_rules_callbacks: {e}")

        registered_spam = False
        if hasattr(self.api, "register_spam_checker_callbacks"):
            try:
                self.api.register_spam_checker_callbacks(
                    user_may_create_room=self.user_may_create_room,
                    user_may_invite=self.user_may_invite,
                    user_may_join_room=self.user_may_join_room,
                    check_media_file_for_spam=self.check_media_file_for_spam,
                )
                registered_spam = True
                logger.warning("[E2EE_TRACE] Registered spam_checker_callbacks successfully (user_may_create_room, etc.)")
            except Exception as e:
                logger.error(f"[E2EE_TRACE] Error registering via register_spam_checker_callbacks: {e}")

        if not registered_3pr and not registered_spam:
            logger.error("[E2EE_TRACE] CRITICAL: Neither third_party_rules nor spam_checker callbacks could be registered on ModuleApi!")

    def _load_rules(self) -> Dict[str, Any]:
        if os.path.exists(self.config_file):
            try:
                with open(self.config_file, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception as e:
                logger.error(f"Error loading user status rules from {self.config_file}: {e}")
        return {}

    def _get_e2ee_policy(self) -> Tuple[str, bool]:
        """
        Returns (policy_str, read_ok_bool).
        FAIL CLOSED: If read/parse error occurs, read_ok is False and policy is STRICTLY_DISABLED.
        """
        if not os.path.exists(self.e2ee_policy_file):
            logger.warning(f"[E2EE_TRACE] [POLICY_FILE_MISSING] Policy file {self.e2ee_policy_file} not found. Defaulting policy to ALLOW.")
            return ("ALLOW", True)
        try:
            with open(self.e2ee_policy_file, "r", encoding="utf-8") as pf:
                pdata = json.load(pf)
                pol = str(pdata.get("policy", "ALLOW")).strip().upper()
                return (pol, True)
        except Exception as pe:
            logger.error(f"[E2EE_TRACE] [E2EE_POLICY_READ_ERROR] Could not read or parse {self.e2ee_policy_file}: {pe}. Defaulting to FAIL-CLOSED (STRICTLY_DISABLED).")
            return ("STRICTLY_DISABLED", False)

    async def check_event_allowed(self, event: Any, state_events: Any = None, *args, **kwargs) -> Union[bool, Tuple[bool, Optional[Dict[str, Any]]]]:
        logger.warning(f"[E2EE_TRACE] check_event_allowed CALLED for event_type={getattr(event, 'type', None)}")
        event_type, room_id, sender = _extract_event_info(event)

        policy, read_ok = self._get_e2ee_policy()

        # 1. AUTHORITATIVE E2EE LOCKDOWN ENFORCEMENT
        if event_type == "m.room.encryption":
            logger.warning(
                f"[E2EE_TRACE] event_type={event_type} room_id={room_id} sender={sender} policy={policy} read_ok={read_ok}"
            )
            # FAIL-CLOSED FOR E2EE: If policy is STRICTLY_DISABLED or if reading policy failed
            if policy == "STRICTLY_DISABLED" or not read_ok:
                logger.warning(
                    f"[E2EE_TRACE] REJECTED m.room.encryption event for room={room_id} sender={sender} (policy={policy}, read_ok={read_ok})"
                )
                if SynapseError and Codes:
                    raise SynapseError(403, "End-to-end encryption is disabled by organization policy.", Codes.FORBIDDEN)
                return (False, {
                    "errcode": "M_FORBIDDEN",
                    "error": "End-to-end encryption is disabled by organization policy.",
                    "code": 403
                })

        # 2. USER FLAGS ENFORCEMENT (Locked / Erased / Suspended)
        try:
            if sender:
                rules = self._load_rules()
                user_rule = rules.get(sender) or rules.get(sender.lower())
                if user_rule:
                    if user_rule.get("isLocked") or user_rule.get("isErased"):
                        logger.warning(f"UserFlagsModule: blocking event for locked/erased user {sender}")
                        return False
                    if user_rule.get("isSuspended"):
                        logger.warning(f"UserFlagsModule: blocking write event for suspended user {sender}")
                        return False
        except Exception as err:
            logger.error(f"UserFlagsModule error in check_event_allowed user_rules: {err}")

        return True

    async def check_media_file_for_spam(self, file_info: Any = None, user_id: str = None, *args, **kwargs) -> bool:
        try:
            uid = user_id or (args[0] if args and isinstance(args[0], str) else None)
            if uid:
                rules = self._load_rules()
                user_rule = rules.get(uid) or rules.get(uid.lower())
                if user_rule and (user_rule.get("isLocked") or user_rule.get("isErased") or user_rule.get("isSuspended")):
                    logger.warning(f"UserFlagsModule: blocking media upload for user {uid}")
                    return False
        except Exception as err:
            logger.error(f"UserFlagsModule error in check_media_file_for_spam: {err}")
        return True

    async def user_may_invite(self, inviter: str = None, invitee: str = None, room_id: str = None, *args, **kwargs) -> bool:
        try:
            uid = inviter or (args[0] if args and isinstance(args[0], str) else None)
            if uid:
                rules = self._load_rules()
                user_rule = rules.get(uid) or rules.get(uid.lower())
                if user_rule and (user_rule.get("isLocked") or user_rule.get("isErased") or user_rule.get("isSuspended")):
                    logger.warning(f"UserFlagsModule: blocking room invite for user {uid}")
                    return False
        except Exception as err:
            logger.error(f"UserFlagsModule error in user_may_invite: {err}")
        return True

    async def user_may_join_room(self, user_id: str = None, room_id: str = None, *args, **kwargs) -> bool:
        try:
            uid = user_id or (args[0] if args and isinstance(args[0], str) else None)
            if uid:
                rules = self._load_rules()
                user_rule = rules.get(uid) or rules.get(uid.lower())
                if user_rule and (user_rule.get("isLocked") or user_rule.get("isErased")):
                    logger.warning(f"UserFlagsModule: blocking room join for user {uid}")
                    return False
        except Exception as err:
            logger.error(f"UserFlagsModule error in user_may_join_room: {err}")
        return True

    async def user_may_create_room(self, user_id: str = None, *args, **kwargs) -> bool:
        uid = user_id
        if not uid and args and isinstance(args[0], str):
            uid = args[0]

        config = None
        for arg in args:
            if isinstance(arg, dict):
                config = arg
                break
        if not config and "config" in kwargs and isinstance(kwargs["config"], dict):
            config = kwargs["config"]

        # 1. AUTHORITATIVE E2EE LOCKDOWN FOR ENCRYPTED ROOM CREATION
        if config and _is_encrypted_room_config(config):
            policy, read_ok = self._get_e2ee_policy()
            logger.warning(
                f"[E2EE_TRACE] user_may_create_room sender={uid} policy={policy} read_ok={read_ok} config_encrypted=True"
            )
            if policy == "STRICTLY_DISABLED" or not read_ok:
                logger.warning(
                    f"[E2EE_TRACE] REJECTED encrypted room creation by sender={uid} (policy={policy}, read_ok={read_ok})"
                )
                if SynapseError and Codes:
                    raise SynapseError(403, "End-to-end encryption is disabled by organization policy.", Codes.FORBIDDEN)
                return False

        # 2. USER FLAGS ENFORCEMENT
        try:
            if uid:
                rules = self._load_rules()
                user_rule = rules.get(uid) or rules.get(uid.lower())
                if user_rule and (user_rule.get("isLocked") or user_rule.get("isErased") or user_rule.get("isSuspended")):
                    logger.warning(f"UserFlagsModule: blocking room creation for user {uid}")
                    return False
        except Exception as err:
            logger.error(f"UserFlagsModule error in user_may_create_room user_rules: {err}")

        return True

CorporatePolicyModule = UserFlagsModule
`;

interface SynapsePythonEnvironment {
  serviceName: string;
  serviceExecStart: string;
  pythonBin: string;
  pythonVersion: string;
  sitePackagesDir: string;
  sysPath: string[];
  isVerified: boolean;
}

async function discoverSynapsePythonEnvironment(activeConn: any, logSteps?: string[]): Promise<SynapsePythonEnvironment> {
  const log = (msg: string) => {
    console.log(msg);
    if (logSteps && Array.isArray(logSteps)) {
      logSteps.push(msg);
    }
  };

  log("[SYNAPSE DISCOVERY] Discovering active Synapse service and runtime Python interpreter...");

  // 1. Discover active Synapse systemd service & running process
  const discoveryScript = `
SERVICE=""
EXEC_START=""
PID_EXEC=""

if command -v systemctl >/dev/null 2>&1; then
  if systemctl is-active --quiet matrix-synapse 2>/dev/null || systemctl list-unit-files matrix-synapse.service 2>/dev/null | grep -q "matrix-synapse"; then
    SERVICE="matrix-synapse"
  elif systemctl is-active --quiet synapse 2>/dev/null || systemctl list-unit-files synapse.service 2>/dev/null | grep -q "synapse"; then
    SERVICE="synapse"
  else
    FOUND=$(systemctl list-unit-files 2>/dev/null | grep -iE "^(matrix-)?synapse" | head -n 1 | awk '{print $1}')
    if [ -n "$FOUND" ]; then SERVICE="$FOUND"; fi
  fi

  if [ -n "$SERVICE" ]; then
    EXEC_START=$(systemctl show "$SERVICE" -p ExecStart --no-page 2>/dev/null || true)
  fi
fi

# Also inspect running processes for Synapse homeserver
PROC_LINE=$(ps -eo pid,args 2>/dev/null | grep -E "synapse\.app\.homeserver|synctl" | grep -v "grep" | head -n 1 || true)

echo "DISCOVERY_SERVICE:$SERVICE"
echo "DISCOVERY_EXEC_START:$EXEC_START"
echo "DISCOVERY_PROC:$PROC_LINE"
`.trim();

  const discOutput = await runServerCommand(discoveryScript, activeConn);

  const svcMatch = discOutput.match(/DISCOVERY_SERVICE:([^\n]*)/);
  const serviceName = (svcMatch && svcMatch[1]) ? svcMatch[1].trim() : "matrix-synapse";

  const execMatch = discOutput.match(/DISCOVERY_EXEC_START:([^\n]*)/);
  const execStart = (execMatch && execMatch[1]) ? execMatch[1].trim() : "";

  const procMatch = discOutput.match(/DISCOVERY_PROC:([^\n]*)/);
  const procLine = (procMatch && procMatch[1]) ? procMatch[1].trim() : "";

  log(`[SYNAPSE DISCOVERY] Target Service: ${serviceName || "standalone/sandbox"} | ExecStart: ${execStart || "none"}`);

  // 2. Extract candidate Python executable from ExecStart or Process
  let candidatePyBin = "";

  if (execStart) {
    const pathMatch = execStart.match(/path=([^;\s\}]+)/) || execStart.match(/^ExecStart=([^\s]+)/);
    if (pathMatch && pathMatch[1]) {
      candidatePyBin = pathMatch[1].trim();
    }
  }

  if (!candidatePyBin && procLine) {
    const tokens = procLine.trim().split(/\s+/);
    if (tokens.length > 1) {
      candidatePyBin = tokens[1];
    }
  }

  // 3. Resolve exact executable and test with target shell
  const resolvePyScript = `
CAND="${candidatePyBin}"
PY=""

test_py() {
  local p="$1"
  if [ -n "$p" ] && [ -x "$p" ]; then
    if "$p" -c "import sys; sys.exit(0)" 2>/dev/null; then
      PY="$p"
      return 0
    fi
  fi
  return 1
}

# Check direct candidate executable
if [ -n "$CAND" ] && [ -x "$CAND" ]; then
  if test_py "$CAND"; then
    echo "RESOLVED_BIN:$PY"
    exit 0
  fi
  # If candidate is a script wrapper (e.g. synctl), inspect shebang
  SHEBANG=$(head -n 1 "$CAND" 2>/dev/null || true)
  if [[ "$SHEBANG" =~ ^#!\s*([^[:space:]]+) ]]; then
    SB_BIN="\${BASH_REMATCH[1]}"
    if test_py "$SB_BIN"; then
      echo "RESOLVED_BIN:$PY"
      exit 0
    fi
  fi
  # If candidate is in a virtualenv bin dir, look for python in that directory
  CAND_DIR=$(dirname "$CAND")
  if test_py "$CAND_DIR/python" || test_py "$CAND_DIR/python3"; then
    echo "RESOLVED_BIN:$PY"
    exit 0
  fi
fi

# Check standard Synapse Virtualenv if present
if test_py "/opt/venvs/matrix-synapse/bin/python" || test_py "/opt/venvs/matrix-synapse/bin/python3"; then
  echo "RESOLVED_BIN:$PY"
  exit 0
fi

# Check system Pythons with Synapse module installed
for sys_py in python3 python /usr/bin/python3 /usr/local/bin/python3; do
  if command -v "$sys_py" >/dev/null 2>&1; then
    FULL_PATH=$(command -v "$sys_py")
    if "$FULL_PATH" -c "import synapse; sys.exit(0)" 2>/dev/null; then
      echo "RESOLVED_BIN:$FULL_PATH"
      exit 0
    fi
  fi
done

# Fallback to general python3 or python
if command -v python3 >/dev/null 2>&1; then
  echo "RESOLVED_BIN:$(command -v python3)"
  exit 0
elif command -v python >/dev/null 2>&1; then
  echo "RESOLVED_BIN:$(command -v python)"
  exit 0
fi

echo "RESOLVED_BIN:"
`.trim();

  const resolveOutput = await runServerCommand(resolvePyScript, activeConn);
  const resolvedMatch = resolveOutput.match(/RESOLVED_BIN:([^\n]*)/);
  const pythonBin = (resolvedMatch && resolvedMatch[1]) ? resolvedMatch[1].trim() : "";

  if (!pythonBin) {
    throw new Error(`Failed to discover a verified Python interpreter for Synapse (Service: ${serviceName}, ExecStart: ${execStart || "none"}).`);
  }

  log(`[SYNAPSE DISCOVERY] Detected Synapse Python interpreter: ${pythonBin}`);

  // 4. Query that EXACT Python interpreter for its runtime sys.path and site-packages
  const pyEnvProbeCmd = `${pythonBin} - <<'PYEOF'
import sys, os, site, sysconfig, json

res = {
  "python_version": sys.version.split()[0],
  "executable": sys.executable,
  "prefix": sys.prefix,
  "sys_path": sys.path,
  "candidates": [],
  "preferred": None
}

candidates = []
try:
  for p in site.getsitepackages():
    if p and p not in candidates:
      candidates.append(p)
except Exception:
  pass

for key in ["purelib", "platlib"]:
  try:
    p = sysconfig.get_path(key)
    if p and p not in candidates:
      candidates.append(p)
  except Exception:
    pass

for p in sys.path:
  if p and ("site-packages" in p or "dist-packages" in p) and p not in candidates:
    candidates.append(p)

resolved = []
for c in candidates:
  if not c or not isinstance(c, str):
    continue
  norm = os.path.normpath(c)
  on_sys_path = any(os.path.normpath(sp) == norm for sp in sys.path)
  exists = os.path.exists(norm)
  is_dir = os.path.isdir(norm) if exists else False
  resolved.append({
    "path": norm,
    "exists": exists,
    "is_dir": is_dir,
    "on_sys_path": on_sys_path
  })

# Determine preferred site-packages: must exist, be a directory, and be on sys.path
preferred = None
for r in resolved:
  if r["exists"] and r["is_dir"] and r["on_sys_path"]:
    preferred = r["path"]
    break

if not preferred:
  for r in resolved:
    if r["exists"] and r["is_dir"]:
      preferred = r["path"]
      break

if not preferred and resolved:
  preferred = resolved[0]["path"]

res["candidates"] = resolved
res["preferred"] = preferred

print("SYNAPSE_PY_RESOLVE:" + json.dumps(res))
PYEOF
`.trim();

  const probeOutput = await runServerCommand(pyEnvProbeCmd, activeConn);
  const probeMatch = probeOutput.match(/SYNAPSE_PY_RESOLVE:([^\n]+)/);

  if (!probeMatch || !probeMatch[1]) {
    throw new Error(`Failed to query runtime Python environment from interpreter ${pythonBin}: ${probeOutput}`);
  }

  let probeData: any;
  try {
    probeData = JSON.parse(probeMatch[1]);
  } catch (parseErr: any) {
    throw new Error(`Invalid JSON returned from Python interpreter ${pythonBin}: ${parseErr.message}`);
  }

  const pythonVersion = probeData.python_version || "unknown";
  const sitePackagesDir = probeData.preferred;
  const sysPath = Array.isArray(probeData.sys_path) ? probeData.sys_path : [];

  if (!sitePackagesDir) {
    throw new Error(`Could not resolve a valid site-packages directory for Synapse interpreter ${pythonBin} (Python ${pythonVersion}).`);
  }

  log(`[SYNAPSE DISCOVERY] Verified Python v${pythonVersion} (executable: ${pythonBin})`);
  log(`[SYNAPSE DISCOVERY] Resolved Synapse site-packages: ${sitePackagesDir}`);

  return {
    serviceName,
    serviceExecStart: execStart,
    pythonBin,
    pythonVersion,
    sitePackagesDir,
    sysPath,
    isVerified: true
  };
}

async function ensureSynapseUserFlagsModuleInstalled(activeConn: any, logSteps?: string[]): Promise<{
  success: boolean;
  serviceName: string;
  pythonBin: string;
  pythonVersion: string;
  sitePackagesDir: string;
  installedLocations: string[];
  validationResult: string;
}> {
  const log = (msg: string) => {
    console.log(msg);
    if (logSteps && Array.isArray(logSteps)) {
      logSteps.push(msg);
    }
  };

  // 1. Dynamic runtime discovery of the exact Synapse Python interpreter
  const env = await discoverSynapsePythonEnvironment(activeConn, logSteps);

  const installedLocations: string[] = [];

  // 2. Write primary module to canonical Synapse module locations
  const primaryConfigs = [
    "/etc/matrix-synapse/matrix_user_flags_module.py",
    "/etc/matrix-synapse/modules/corporate_policy.py"
  ];

  for (const cfgPath of primaryConfigs) {
    const ok = await writeConfigContent(cfgPath, SYNAPSE_USER_FLAGS_PYTHON_CODE);
    if (ok) {
      installedLocations.push(cfgPath);
      log(`[SYNAPSE MODULE] Wrote primary module file: ${cfgPath}`);
    } else {
      throw new Error(`Failed to write Synapse module to ${cfgPath}`);
    }
  }

  // 3. Write module ONLY into the verified site-packages directory of the Synapse Python interpreter
  const targetSitePackagesModule = path.posix.join(env.sitePackagesDir, "matrix_user_flags_module.py");
  
  const writeTargetOk = await writeConfigContent(targetSitePackagesModule, SYNAPSE_USER_FLAGS_PYTHON_CODE);
  if (!writeTargetOk) {
    // If standard file write failed due to permissions on remote SSH, use sudo cp from /etc/matrix-synapse/matrix_user_flags_module.py
    if (activeConn && activeConn.authType !== "agent" && activeConn.id !== "local") {
      const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
      const copyCmd = `${sudoPrefix}cp -f /etc/matrix-synapse/matrix_user_flags_module.py "${targetSitePackagesModule}"`;
      await executeSSHCommand(activeConn, copyCmd);
    } else {
      throw new Error(`Failed to install module into Synapse site-packages: ${targetSitePackagesModule}`);
    }
  }
  installedLocations.push(targetSitePackagesModule);
  log(`[SYNAPSE MODULE] Installed module to Synapse runtime site-packages: ${targetSitePackagesModule}`);

  // 4. Verify module import using the exact discovered Python interpreter
  const verifyCmd = `${env.pythonBin} -c "import matrix_user_flags_module; print('MODULE_VERIFY_OK:' + getattr(matrix_user_flags_module, '__file__', 'unknown'))"`;
  const verifyOut = await runServerCommand(verifyCmd, activeConn);

  if (!verifyOut.includes("MODULE_VERIFY_OK:")) {
    throw new Error(`Synapse Python interpreter (${env.pythonBin}) failed to import matrix_user_flags_module: ${verifyOut}`);
  }

  const verifyPath = verifyOut.match(/MODULE_VERIFY_OK:([^\n]+)/)?.[1]?.trim() || targetSitePackagesModule;
  log(`[SYNAPSE MODULE] Module import verified successfully by ${env.pythonBin} (loaded: ${verifyPath})`);

  // 5. Register in /etc/matrix-synapse/homeserver.yaml
  const hsYamlStr = await readConfigContent("/etc/matrix-synapse/homeserver.yaml");
  if (!hsYamlStr || !hsYamlStr.trim()) {
    throw new Error("Could not read /etc/matrix-synapse/homeserver.yaml for module registration.");
  }

  let doc: any;
  try {
    doc = jsYaml.load(hsYamlStr);
  } catch (yamlErr: any) {
    throw new Error(`Invalid YAML syntax in /etc/matrix-synapse/homeserver.yaml: ${yamlErr.message}`);
  }

  if (!doc || typeof doc !== "object") {
    throw new Error("Parsed homeserver.yaml is not a valid YAML mapping object.");
  }

  if (!Array.isArray(doc.modules)) {
    doc.modules = [];
  }

  let moduleObj = doc.modules.find((m: any) => m && typeof m === "object" && m.module === "matrix_user_flags_module.UserFlagsModule");
  let updated = false;

  if (!moduleObj) {
    moduleObj = {
      module: "matrix_user_flags_module.UserFlagsModule",
      config: {
        config_file: "/etc/matrix-synapse/user_status_rules.json",
        e2ee_policy_file: "/etc/matrix-synapse/e2ee_policy.json"
      }
    };
    doc.modules.push(moduleObj);
    updated = true;
  } else {
    if (!moduleObj.config || typeof moduleObj.config !== "object") {
      moduleObj.config = {};
    }
    if (moduleObj.config.config_file !== "/etc/matrix-synapse/user_status_rules.json") {
      moduleObj.config.config_file = "/etc/matrix-synapse/user_status_rules.json";
      updated = true;
    }
    if (moduleObj.config.e2ee_policy_file !== "/etc/matrix-synapse/e2ee_policy.json") {
      moduleObj.config.e2ee_policy_file = "/etc/matrix-synapse/e2ee_policy.json";
      updated = true;
    }
  }

  if (updated) {
    const newYaml = jsYaml.dump(doc, { indent: 2, lineWidth: -1, noRefs: true });
    // Verify YAML integrity
    try {
      jsYaml.load(newYaml);
    } catch (testParseErr: any) {
      throw new Error(`Failed to generate valid YAML for homeserver.yaml: ${testParseErr.message}`);
    }
    const writeYamlOk = await writeConfigContent("/etc/matrix-synapse/homeserver.yaml", newYaml);
    if (!writeYamlOk) {
      throw new Error("Failed to write updated homeserver.yaml configuration.");
    }
    log(`[SYNAPSE MODULE] Successfully registered matrix_user_flags_module.UserFlagsModule in homeserver.yaml`);
  } else {
    log(`[SYNAPSE MODULE] matrix_user_flags_module.UserFlagsModule already properly registered in homeserver.yaml`);
  }

  return {
    success: true,
    serviceName: env.serviceName,
    pythonBin: env.pythonBin,
    pythonVersion: env.pythonVersion,
    sitePackagesDir: env.sitePackagesDir,
    installedLocations,
    validationResult: verifyPath
  };
}

// Capabilities interceptor
app.get([
  "/_matrix/client/v3/capabilities",
  "/_matrix/client/r0/capabilities"
], async (req, res) => {
  try {
    const activeConn = getActiveConnection();
    const user_id = await getUserIdByAccessToken(req, activeConn);
    
    if (user_id) {
      const rule = await getUserStatusRule(user_id);
      if (rule.isLocked) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "حساب کاربری شما توسط مدیر سیستم قفل شده است. / Your account has been locked by your administrator."
        });
      }
      if (rule.isErased) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "این حساب کاربری حذف شده است. / This account has been erased."
        });
      }
    }
    
    const caps = await fetchCapabilitiesFromSynapse(req, activeConn);
    
    if (user_id) {
      const rule = await getUserStatusRule(user_id);
      if (!caps.capabilities) {
        caps.capabilities = {};
      }
      if (rule.disableClientPasswordChange) {
        caps.capabilities["m.change_password"] = { enabled: false };
      }
    }
    
    res.json(caps);
  } catch (err: any) {
    console.error("Capabilities intercept error:", err);
    res.status(500).json({ error: "Internal server error in capabilities interceptor", message: err.message });
  }
});

// Login interceptor to block locked or erased users
app.post([
  "/_matrix/client/v3/login",
  "/_matrix/client/r0/login"
], async (req, res) => {
  try {
    const activeConn = getActiveConnection();
    
    let username = "";
    const body = req.body || {};
    if (body.identifier) {
      if (body.identifier.user) {
        username = body.identifier.user;
      }
    } else if (body.user) {
      username = body.user;
    }
    
    if (username) {
      let mxid = username;
      if (!mxid.startsWith("@")) {
        const domain = (activeConn as any)?.HS_DOMAIN || "matrix.company.local";
        mxid = `@${username}:${domain}`;
      } else if (!mxid.includes(":")) {
        const domain = (activeConn as any)?.HS_DOMAIN || "matrix.company.local";
        mxid = `${mxid}:${domain}`;
      }
      
      const rule = await getUserStatusRule(mxid);
      if (rule.isLocked) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "حساب کاربری شما توسط مدیر سیستم قفل شده است. / Your account has been locked by your administrator."
        });
      }
      if (rule.isErased) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "این حساب کاربری حذف شده است. / This account has been erased."
        });
      }
    }
    
    await forwardRequestToSynapse(req, res, "POST", activeConn);
  } catch (err: any) {
    console.error("Login intercept error:", err);
    res.status(500).json({ error: "Internal server error in login interceptor", message: err.message });
  }
});

// Core room write actions interceptor
app.all([
  "/_matrix/client/v3/rooms/:roomId/send/:eventType",
  "/_matrix/client/v3/rooms/:roomId/send/:eventType/:txnId",
  "/_matrix/client/r0/rooms/:roomId/send/:eventType",
  "/_matrix/client/r0/rooms/:roomId/send/:eventType/:txnId",
  "/_matrix/client/v3/rooms/:roomId/state/:eventType",
  "/_matrix/client/v3/rooms/:roomId/state/:eventType/:stateKey",
  "/_matrix/client/r0/rooms/:roomId/state/:eventType",
  "/_matrix/client/r0/rooms/:roomId/state/:eventType/:stateKey",
  "/_matrix/client/v3/rooms/:roomId/join",
  "/_matrix/client/r0/rooms/:roomId/join",
  "/_matrix/client/v3/rooms/:roomId/invite",
  "/_matrix/client/r0/rooms/:roomId/invite",
  "/_matrix/client/v3/createRoom",
  "/_matrix/client/r0/createRoom",
  "/_matrix/media/v3/upload",
  "/_matrix/media/r0/upload",
  "/_matrix/client/v3/upload"
], async (req, res) => {
  try {
    const activeConn = getActiveConnection();
    const user_id = await getUserIdByAccessToken(req, activeConn);
    
    if (user_id) {
      const rule = await getUserStatusRule(user_id);
      
      if (rule.isLocked) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "حساب کاربری شما توسط مدیر سیستم قفل شده است. / Your account has been locked by your administrator."
        });
      }
      if (rule.isErased) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "این حساب کاربری حذف شده است. / This account has been erased."
        });
      }
      if (rule.isSuspended) {
        return res.status(403).json({
          errcode: "M_FORBIDDEN",
          error: "حساب کاربری شما به حالت تعلیق درآمده و در وضعیت فقط‌خواندنی قرار دارد. / Your account is suspended and in read-only mode."
        });
      }
      if (rule.isShadowBanned) {
        const pathLower = req.path.toLowerCase();
        if (pathLower.includes("/send") || pathLower.includes("/state")) {
          return res.json({
            event_id: `$shadow_event_${Math.random().toString(36).substring(2, 15)}`
          });
        }
      }
    }
    
    // --- E2EE ORGANIZATION POLICY LOCKDOWN ENFORCEMENT ---
    const effectivePolicy = await getEffectiveE2EEPolicy();
    if (effectivePolicy === "STRICTLY_DISABLED") {
      const pathLower = req.path.toLowerCase();
      const eventTypeParam = req.params?.eventType;

      // 1. Block m.room.encryption state events
      if (
        eventTypeParam === "m.room.encryption" ||
        pathLower.includes("/state/m.room.encryption") ||
        pathLower.includes("/send/m.room.encryption")
      ) {
        console.warn(`[E2EE POLICY INTERCEPT] Blocked E2EE state event for room ${req.params?.roomId || 'unknown'} by user ${user_id || 'unknown'}`);
        return res.status(403).json({
          code: "E2EE_ORG_POLICY_BLOCKED",
          errcode: "E2EE_ORG_POLICY_BLOCKED",
          error: "End-to-end encryption is disabled by the organization policy.",
          message: "End-to-end encryption is disabled by the organization policy."
        });
      }

      // 2. Block createRoom requesting encryption
      if (pathLower.includes("/createroom")) {
        const body = req.body || {};
        const hasEncInInitialState = Array.isArray(body.initial_state) && body.initial_state.some((st: any) => st && st.type === "m.room.encryption");
        const hasEncInCreationContent = body.creation_content && body.creation_content["m.room.encryption"];
        const explicitEncryption = body.isEncrypted === true || body.enableEncryption === true || hasEncInInitialState || hasEncInCreationContent;

        if (explicitEncryption) {
          console.warn(`[E2EE POLICY INTERCEPT] Blocked createRoom with encryption request by user ${user_id || 'unknown'}`);
          return res.status(403).json({
            code: "E2EE_ORG_POLICY_BLOCKED",
            errcode: "E2EE_ORG_POLICY_BLOCKED",
            error: "End-to-end encryption is disabled by the organization policy.",
            message: "End-to-end encryption is disabled by the organization policy."
          });
        }
      }
    }

    await forwardRequestToSynapse(req, res, req.method, activeConn);
  } catch (err: any) {
    console.error("Client action intercept error:", err);
    res.status(500).json({ error: "Internal server error in client action interceptor", message: err.message });
  }
});

