// ============================================================================
// DYNAMIC SYNAPSE CONFIGURATION TARGET DISCOVERY & AUTO-JOIN ROOMS MANAGEMENT
// ============================================================================

interface SynapseConfigTarget {
  serviceName: string;
  pythonBin: string;
  pythonVersion: string;
  serverName: string;
  type: "directory_file" | "homeserver_yaml";
  configDirectory: string | null;
  canonicalAutoJoinFile: string;
  homeserverYamlPath: string;
  allLoadedConfigPaths: string[];
  existingAutoJoinFiles: string[];
}

/**
 * Dynamically discovers the active Synapse runtime configuration paths
 * by inspecting the running systemd service (ExecStart) and process command line.
 * Resolves whether a configuration directory (e.g. conf.d) is loaded or a standalone homeserver.yaml.
 */
async function discoverSynapseConfigTarget(activeConn: any, logSteps?: string[]): Promise<SynapseConfigTarget> {
  const log = (msg: string) => {
    console.log(msg);
    if (logSteps && Array.isArray(logSteps)) logSteps.push(msg);
  };

  log("[SYNAPSE CONFIG DISCOVERY] Probing active Synapse runtime and configuration paths...");

  // 1. Discover Python interpreter and service name
  const pyEnv = await discoverSynapsePythonEnvironment(activeConn, logSteps);
  const serviceName = pyEnv.serviceName || "matrix-synapse";

  // 2. Discover runtime flags from systemd ExecStart and running process
  const probeScript = `
SERVICE="${serviceName}"
EXEC_START=""
PROC_CMD=""

if command -v systemctl >/dev/null 2>&1 && [ -n "$SERVICE" ]; then
  EXEC_START=$(systemctl show "$SERVICE" -p ExecStart --no-page 2>/dev/null || true)
fi

PROC_CMD=$(ps -eo pid,args 2>/dev/null | grep -E "synapse\\.app\\.homeserver|synctl" | grep -v "grep" | head -n 1 || true)

echo "DISC_EXEC_START:$EXEC_START"
echo "DISC_PROC_CMD:$PROC_CMD"
`.trim();

  const probeOutput = await runServerCommand(probeScript, activeConn);
  const execMatch = probeOutput.match(/DISC_EXEC_START:([^\n]*)/);
  const execStart = (execMatch && execMatch[1]) ? execMatch[1].trim() : "";
  const procMatch = probeOutput.match(/DISC_PROC_CMD:([^\n]*)/);
  const procCmd = (procMatch && procMatch[1]) ? procMatch[1].trim() : "";

  // 3. Extract all explicit --config-path / -c flags
  const rawFlags: string[] = [];
  const combinedText = `${execStart} ${procCmd}`;
  const flagRegex = /(?:--config-path[=\s]|-c\s+)([^\s;\}]+)/g;
  let m: RegExpExecArray | null;
  while ((m = flagRegex.exec(combinedText)) !== null) {
    if (m[1] && m[1].trim()) {
      rawFlags.push(m[1].trim().replace(/^["']|["']$/g, ""));
    }
  }

  if (activeConn && activeConn.homeserverYamlPath) {
    rawFlags.push(activeConn.homeserverYamlPath);
  }

  // 4. Test discovered paths on target server filesystem
  const pathsJson = JSON.stringify(Array.from(new Set(rawFlags)));
  const pathTestScript = `
PYTHON_BIN="${pyEnv.pythonBin}"

$PYTHON_BIN - <<'PYEOF'
import sys, os, json

raw_candidates = json.loads('''${pathsJson}''')
standard_hs_paths = [
    "/etc/matrix-synapse/homeserver.yaml",
    "/etc/synapse/homeserver.yaml",
    "/var/lib/matrix-synapse/homeserver.yaml"
]

resolved_dirs = []
resolved_files = []

for c in raw_candidates:
    if not c or not isinstance(c, str):
        continue
    norm = os.path.normpath(c)
    if os.path.isdir(norm):
        if norm not in resolved_dirs:
            resolved_dirs.append(norm)
    elif os.path.isfile(norm):
        if norm not in resolved_files:
            resolved_files.append(norm)

# If no file found from flags, check standard locations
homeserver_yaml = None
for f in resolved_files:
    if f.endswith("homeserver.yaml") or f.endswith(".yaml") or f.endswith(".yml"):
        homeserver_yaml = f
        break

if not homeserver_yaml:
    for sh in standard_hs_paths:
        if os.path.isfile(sh):
            homeserver_yaml = sh
            if sh not in resolved_files:
                resolved_files.append(sh)
            break

# If homeserver.yaml is found, check if a conf.d directory exists next to it
config_dir = None
if resolved_dirs:
    # Prefer explicitly loaded config directory
    config_dir = resolved_dirs[0]
elif homeserver_yaml:
    adjacent_confd = os.path.join(os.path.dirname(homeserver_yaml), "conf.d")
    if os.path.isdir(adjacent_confd):
        config_dir = adjacent_confd

# Scan config_dir for existing auto-join files
existing_autojoin_files = []
canonical_file = None

if config_dir and os.path.isdir(config_dir):
    try:
        entries = sorted(os.listdir(config_dir))
        for entry in entries:
            if entry.endswith((".yaml", ".yml")) and ("auto_join" in entry or "autojoin" in entry):
                full_p = os.path.join(config_dir, entry)
                existing_autojoin_files.append(full_p)
    except Exception:
        pass

    if existing_autojoin_files:
        preferred = next((f for f in existing_autojoin_files if os.path.basename(f) == "auto_join_rooms.yaml"), existing_autojoin_files[0])
        canonical_file = preferred
    else:
        canonical_file = os.path.join(config_dir, "auto_join_rooms.yaml")
elif homeserver_yaml:
    canonical_file = homeserver_yaml

# Read server_name from homeserver_yaml if possible
server_name = None
if homeserver_yaml and os.path.isfile(homeserver_yaml):
    try:
        import yaml
        with open(homeserver_yaml, "r", encoding="utf-8") as f:
            doc = yaml.safe_load(f)
            if isinstance(doc, dict) and doc.get("server_name"):
                server_name = str(doc["server_name"]).strip()
    except Exception:
        pass

result = {
    "homeserver_yaml": homeserver_yaml,
    "config_dir": config_dir,
    "canonical_file": canonical_file,
    "existing_autojoin_files": existing_autojoin_files,
    "resolved_files": resolved_files,
    "resolved_dirs": resolved_dirs,
    "server_name": server_name
}

print("CONFIG_RESOLVE:" + json.dumps(result))
PYEOF
`.trim();

  const testOutput = await runServerCommand(pathTestScript, activeConn);
  const match = testOutput.match(/CONFIG_RESOLVE:([^\n]+)/);

  let resolveData: any = null;
  if (match && match[1]) {
    try {
      resolveData = JSON.parse(match[1]);
    } catch (_) {}
  }

  // If local sandbox / fallback via readConfigContent
  let homeserverYamlPath = resolveData?.homeserver_yaml || "";
  let configDirectory = resolveData?.config_dir || null;
  let canonicalAutoJoinFile = resolveData?.canonical_file || "";
  const existingAutoJoinFiles: string[] = Array.isArray(resolveData?.existing_autojoin_files) ? resolveData.existing_autojoin_files : [];
  let serverName = resolveData?.server_name || "";

  if (!homeserverYamlPath) {
    const sample = await readConfigContent("/etc/matrix-synapse/homeserver.yaml", "");
    if (sample && sample.trim()) {
      homeserverYamlPath = "/etc/matrix-synapse/homeserver.yaml";
    } else {
      const sample2 = await readConfigContent("/etc/synapse/homeserver.yaml", "");
      if (sample2 && sample2.trim()) {
        homeserverYamlPath = "/etc/synapse/homeserver.yaml";
      }
    }
  }

  if (!canonicalAutoJoinFile) {
    if (configDirectory) {
      canonicalAutoJoinFile = path.join(configDirectory, "auto_join_rooms.yaml");
    } else if (homeserverYamlPath) {
      canonicalAutoJoinFile = homeserverYamlPath;
    } else {
      throw new Error("Failed to discover a valid Synapse configuration file or directory on the target server.");
    }
  }

  // Domain resolution
  if (!serverName) {
    if (activeConn && (activeConn as any).HS_DOMAIN) {
      serverName = (activeConn as any).HS_DOMAIN;
    } else if (activeConn && (activeConn as any).serverName) {
      serverName = (activeConn as any).serverName;
    } else {
      try {
        const confRaw = await readConfigContent("/etc/matrix-stack.conf", "");
        const mDomain = confRaw.match(/^HS_DOMAIN=(.+)$/m);
        if (mDomain && mDomain[1].trim()) serverName = mDomain[1].trim();
      } catch (_) {}
    }
  }

  if (!serverName && homeserverYamlPath) {
    try {
      const hsRaw = await readConfigContent(homeserverYamlPath, "");
      if (hsRaw) {
        const doc: any = yaml.load(hsRaw);
        if (doc && doc.server_name) serverName = String(doc.server_name).trim();
      }
    } catch (_) {}
  }

  if (!serverName) {
    throw new Error("Failed to determine Matrix homeserver server_name/domain from server configuration.");
  }

  const targetType = configDirectory ? "directory_file" : "homeserver_yaml";

  log(`[SYNAPSE CONFIG DISCOVERY] Resolved Config Target Type: ${targetType}`);
  log(`[SYNAPSE CONFIG DISCOVERY] Canonical Auto-Join File: ${canonicalAutoJoinFile}`);
  log(`[SYNAPSE CONFIG DISCOVERY] Synapse Domain: ${serverName}`);

  return {
    serviceName,
    pythonBin: pyEnv.pythonBin,
    pythonVersion: pyEnv.pythonVersion,
    serverName,
    type: targetType,
    configDirectory,
    canonicalAutoJoinFile,
    homeserverYamlPath,
    allLoadedConfigPaths: Array.isArray(resolveData?.resolved_files) ? resolveData.resolved_files : [homeserverYamlPath],
    existingAutoJoinFiles
  };
}

// Helper: Get Homeserver Domain
async function getHomeserverDomain(): Promise<string> {
  const activeConn = getActiveConnection();
  if (activeConn && (activeConn as any).HS_DOMAIN) {
    return (activeConn as any).HS_DOMAIN;
  }
  if (activeConn && (activeConn as any).serverName) {
    return (activeConn as any).serverName;
  }
  try {
    const confRaw = await readConfigContent("/etc/matrix-stack.conf", "");
    const match = confRaw.match(/^HS_DOMAIN=(.+)$/m);
    if (match && match[1].trim()) return match[1].trim();
  } catch (e) {}

  try {
    const hsYaml = await readConfigContent("/etc/matrix-synapse/homeserver.yaml", "");
    if (hsYaml) {
      const doc: any = yaml.load(hsYaml);
      if (doc && doc.server_name) return String(doc.server_name).trim();
    }
  } catch (e) {}

  throw new Error("Failed to discover Matrix homeserver domain from server configuration.");
}

// Helper: Format Auto-Join Room Identifier to #room_alias:domain or valid room ID
function formatAutoJoinRoomIdentifier(rawIdentifier: string, roomObj: any, hsDomain: string): string {
  if (!hsDomain || !hsDomain.trim()) {
    throw new Error("Cannot format room identifier: Homeserver domain is undefined.");
  }
  const domain = hsDomain.trim();

  let candidateAlias = "";
  if (roomObj) {
    candidateAlias = roomObj.canonical_alias || roomObj.alias || (Array.isArray(roomObj.aliases) && roomObj.aliases[0]) || "";
  }

  const str = (rawIdentifier || candidateAlias || "").trim();
  if (!str) {
    throw new Error("Cannot format room identifier: Room identifier is empty.");
  }

  // If already full alias: #bun:chat.company.com
  if (str.startsWith("#") && str.includes(":")) {
    return str;
  }

  // If starts with # but no domain: #bun
  if (str.startsWith("#") && !str.includes(":")) {
    return `${str}:${domain}`;
  }

  // If room ID: !abcdef123:chat.company.com
  if (str.startsWith("!")) {
    // If the room has a canonical alias, use that
    if (candidateAlias && candidateAlias.startsWith("#") && candidateAlias.includes(":")) {
      return candidateAlias;
    }
    // If it's already a valid full room ID with server part, return as is
    if (str.includes(":")) {
      return str;
    }
    return `${str}:${domain}`;
  }

  // If candidateAlias has full alias
  if (candidateAlias && candidateAlias.startsWith("#") && candidateAlias.includes(":")) {
    return candidateAlias;
  }

  // If plain room name or alias slug: bun
  const cleanStr = str.toLowerCase().replace(/[^a-z0-9_=-]/g, '_');
  return `#${cleanStr}:${domain}`;
}

// Helper: Get Auto-Join Rooms from Synapse Config Files
async function getSynapseAutoJoinRooms(): Promise<string[]> {
  const autoJoinList: Set<string> = new Set();
  const activeConn = getActiveConnection();
  const target = await discoverSynapseConfigTarget(activeConn);

  const pathsToRead: string[] = [];
  if (target.type === "directory_file" && target.configDirectory) {
    if (target.canonicalAutoJoinFile) pathsToRead.push(target.canonicalAutoJoinFile);
    if (target.existingAutoJoinFiles && target.existingAutoJoinFiles.length > 0) {
      target.existingAutoJoinFiles.forEach(f => { if (!pathsToRead.includes(f)) pathsToRead.push(f); });
    }
    if (target.homeserverYamlPath && !pathsToRead.includes(target.homeserverYamlPath)) {
      pathsToRead.push(target.homeserverYamlPath);
    }
  } else if (target.homeserverYamlPath) {
    pathsToRead.push(target.homeserverYamlPath);
  }

  for (const p of pathsToRead) {
    try {
      const content = await readConfigContent(p, "");
      if (content && content.trim()) {
        const doc: any = yaml.load(content);
        if (doc && Array.isArray(doc.auto_join_rooms)) {
          doc.auto_join_rooms.forEach((r: any) => {
            if (typeof r === "string" && r.trim()) {
              autoJoinList.add(r.trim());
            }
          });
        }
      }
    } catch (e: any) {
      console.warn(`[AUTO-JOIN] Could not parse config file ${p}:`, e?.message);
    }
  }

  return Array.from(autoJoinList);
}

// Helper: Save Auto-Join Rooms to the single discovered canonical Synapse Config File
async function saveSynapseAutoJoinRooms(rooms: string[]): Promise<{
  success: boolean;
  targetFile: string;
  roomCount: number;
  validationResult: string;
}> {
  const activeConn = getActiveConnection();
  const target = await discoverSynapseConfigTarget(activeConn);

  const cleanRooms = Array.from(new Set(rooms.map(r => formatAutoJoinRoomIdentifier(r, null, target.serverName)).filter(Boolean)));

  let yamlBody = `# Synapse Auto-Join Rooms Configuration\n# Managed by Raven Matrix Admin Panel\nauto_join_rooms:\n`;
  if (cleanRooms.length === 0) {
    yamlBody += "  []\n";
  } else {
    cleanRooms.forEach((rm) => {
      yamlBody += `  - "${rm}"\n`;
    });
  }

  const targetFile = target.canonicalAutoJoinFile;
  if (!targetFile) {
    throw new Error("Unable to resolve canonical Synapse Auto-Join configuration file path.");
  }

  console.log(`[AUTO-JOIN] Writing Auto-Join configuration to discovered canonical file: ${targetFile}`);

  if (target.type === "directory_file") {
    // 1. Write strictly to the canonical configuration file in the discovered configuration directory
    const writeOk = await writeConfigContent(targetFile, yamlBody, {
      component: "Auto-Join Rooms Policy",
      diffSummary: `Updated auto_join_rooms (${cleanRooms.length} room(s)) in ${targetFile}`,
      fieldOrParam: "auto_join_rooms",
      newValue: JSON.stringify(cleanRooms)
    });

    if (!writeOk) {
      throw new Error(`Failed to write Auto-Join configuration to target file: ${targetFile}`);
    }

    // 2. Clean up any obsolete duplicate auto-join files in that same directory to prevent split-brain config
    if (target.existingAutoJoinFiles && target.existingAutoJoinFiles.length > 0) {
      for (const oldFile of target.existingAutoJoinFiles) {
        if (oldFile !== targetFile) {
          try {
            console.log(`[AUTO-JOIN] Removing legacy duplicate auto-join file: ${oldFile}`);
            if (activeConn && activeConn.id !== "local") {
              const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
              await runServerCommand(`${sudoPrefix}rm -f "${oldFile}"`, activeConn);
            }
          } catch (cleanErr: any) {
            console.warn(`[AUTO-JOIN] Could not remove legacy duplicate file ${oldFile}:`, cleanErr.message);
          }
        }
      }
    }
  } else {
    // Standalone homeserver.yaml without a separate conf.d directory
    const hsRaw = await readConfigContent(target.homeserverYamlPath, "");
    let doc: any = {};
    if (hsRaw && hsRaw.trim()) {
      doc = yaml.load(hsRaw) || {};
    }
    doc.auto_join_rooms = cleanRooms;
    const updatedHs = yaml.dump(doc, { indent: 2, lineWidth: -1 });

    const writeOk = await writeConfigContent(target.homeserverYamlPath, updatedHs, {
      component: "Synapse Homeserver Config",
      diffSummary: `Updated auto_join_rooms (${cleanRooms.length} room(s)) in ${target.homeserverYamlPath}`,
      fieldOrParam: "auto_join_rooms",
      newValue: JSON.stringify(cleanRooms)
    });

    if (!writeOk) {
      throw new Error(`Failed to update Auto-Join configuration in ${target.homeserverYamlPath}`);
    }
  }

  // 3. Validation: Verify target file exists and contains valid YAML and expected keys using Python runtime
  const validateScript = `
TARGET_FILE="${targetFile}"
PYTHON_BIN="${target.pythonBin}"

$PYTHON_BIN - <<'PYEOF'
import sys, os, yaml, json

target_file = "${targetFile}"

if not os.path.isfile(target_file):
    sys.stderr.write(f"ERROR: Target file {target_file} does not exist on disk.\\n")
    sys.exit(1)

try:
    with open(target_file, "r", encoding="utf-8") as f:
        data = yaml.safe_load(f)
    if not isinstance(data, dict):
        sys.stderr.write(f"ERROR: Expected YAML mapping, got {type(data).__name__}\\n")
        sys.exit(1)
    if "auto_join_rooms" not in data:
        sys.stderr.write("ERROR: 'auto_join_rooms' key missing in parsed configuration.\\n")
        sys.exit(1)
    rooms = data["auto_join_rooms"]
    if not isinstance(rooms, list):
        sys.stderr.write(f"ERROR: 'auto_join_rooms' must be a list, got {type(rooms).__name__}\\n")
        sys.exit(1)
    print("VALIDATION_OK:" + json.dumps({"count": len(rooms), "rooms": rooms}))
except Exception as err:
    sys.stderr.write(f"ERROR: YAML validation failed: {str(err)}\\n")
    sys.exit(1)
PYEOF
`.trim();

  const validateOut = await runServerCommand(validateScript, activeConn);
  if (!validateOut.includes("VALIDATION_OK:")) {
    throw new Error(`Synapse Auto-Join configuration validation failed: ${validateOut.trim()}`);
  }

  console.log(`[AUTO-JOIN] Configuration file validated successfully: ${targetFile}`);

  // 4. Restart Synapse service and verify service state
  console.log(`[AUTO-JOIN] Restarting Synapse service (${target.serviceName})...`);
  const restartSuccess = await restartSynapseService(activeConn);
  if (!restartSuccess) {
    throw new Error(`Synapse service restart failed for service ${target.serviceName}.`);
  }

  // 5. Verify active service status
  const statusCheckScript = `
SERVICE="${target.serviceName}"
if command -v systemctl >/dev/null 2>&1 && [ -n "$SERVICE" ]; then
  if systemctl is-active --quiet "$SERVICE" 2>/dev/null; then
    echo "SERVICE_STATUS:active"
  else
    echo "SERVICE_STATUS:inactive"
  fi
else
  echo "SERVICE_STATUS:active"
fi
`.trim();

  const statusOut = await runServerCommand(statusCheckScript, activeConn);
  if (statusOut.includes("SERVICE_STATUS:inactive")) {
    throw new Error(`Synapse service ${target.serviceName} is not active after configuration reload.`);
  }

  return {
    success: true,
    targetFile,
    roomCount: cleanRooms.length,
    validationResult: `Verified on ${targetFile} and service ${target.serviceName} is active.`
  };
}

