app.post(["/api/matrix/config/display-name-policy", "/api/matrix/config/profile-policy"], authenticateToken, async (req, res) => {
  try {
    const { enabled, displayNameEnabled, avatarEnabled } = req.body;
    
    const targetDisplayName = typeof displayNameEnabled === "boolean" 
      ? displayNameEnabled 
      : (typeof enabled === "boolean" ? enabled : undefined);

    const targetAvatar = typeof avatarEnabled === "boolean" 
      ? avatarEnabled 
      : (typeof enabled === "boolean" ? enabled : undefined);

    if (targetDisplayName === undefined && targetAvatar === undefined) {
      return res.status(400).json({ error: "Invalid request payload. Boolean field required." });
    }

    const activeConn = getActiveConnection();
    await migrateOldConfDBackups(activeConn);

    const discovery = await discoverDisplayNamePolicy();
    const targetPath = discovery.sourceFile || "/etc/synapse/conf.d/display_name.yaml";

    const rawContent = await readConfigContent(targetPath, "");
    let doc: any = {};
    if (rawContent && rawContent.trim()) {
      try {
        doc = yaml.load(rawContent) || {};
      } catch (e) {
        doc = {};
      }
    }
    if (typeof doc !== "object" || doc === null) {
      doc = {};
    }

    // Clean up enable_room_creation from YAML files (must not exist in Synapse YAML config)
    delete doc.enable_room_creation;

    // Backup current file before writing (stored in /etc/synapse/config-backups/)
    const timestamp = Date.now();
    const backupPath = getBackupFilePath(targetPath, timestamp);
    if (rawContent && rawContent.trim()) {
      await writeConfigContent(backupPath, rawContent);
    }

    // Set/update enable_set_displayname and enable_set_avatar_url independently
    if (targetDisplayName !== undefined) {
      doc.enable_set_displayname = targetDisplayName;
    }
    if (targetAvatar !== undefined) {
      doc.enable_set_avatar_url = targetAvatar;
    }
    const newYaml = yaml.dump(doc, { indent: 2, lineWidth: -1 });

    // Write new content to target path
    const writeOk = await writeConfigContent(targetPath, newYaml);
    if (!writeOk) {
      return res.status(500).json({ error: "Failed to write target configuration file" });
    }

    // Also check and synchronize all other conf.d files & homeserver.yaml files
    const confDFiles = await listConfDFiles(activeConn);
    const hsPaths = ["/etc/matrix-synapse/homeserver.yaml", "/etc/synapse/homeserver.yaml"];
    if (activeConn && activeConn.homeserverYamlPath && !hsPaths.includes(activeConn.homeserverYamlPath)) {
      hsPaths.push(activeConn.homeserverYamlPath);
    }
    const allCheckPaths = Array.from(new Set([...confDFiles, ...hsPaths]));

    for (const checkPath of allCheckPaths) {
      if (checkPath === targetPath) continue;
      const isHsFile = hsPaths.includes(checkPath);
      const otherContent = await readConfigContent(checkPath, "");
      if (!isHsFile && (!otherContent || !otherContent.trim())) continue;

      try {
        let otherDoc: any = {};
        if (otherContent && otherContent.trim()) {
          otherDoc = yaml.load(otherContent) || {};
        }
        if (typeof otherDoc !== "object" || otherDoc === null) {
          otherDoc = {};
        }

        // Always clean up enable_room_creation from YAML files
        delete otherDoc.enable_room_creation;

        const hasDisplayNameKey = "enable_set_displayname" in otherDoc;
        const hasAvatarKey = "enable_set_avatar_url" in otherDoc;
        
        if (hasDisplayNameKey || hasAvatarKey || isHsFile) {
          if (targetDisplayName !== undefined) {
            otherDoc.enable_set_displayname = targetDisplayName;
          }
          if (targetAvatar !== undefined) {
            otherDoc.enable_set_avatar_url = targetAvatar;
          }
          const otherYaml = yaml.dump(otherDoc, { indent: 2, lineWidth: -1 });
          if (otherContent && otherContent.trim()) {
            const otherBackupPath = getBackupFilePath(checkPath, timestamp);
            await writeConfigContent(otherBackupPath, otherContent);
          }
          await writeConfigContent(checkPath, otherYaml);
        }
      } catch (e) {
        // Skip files that fail to parse
      }
    }

    // Immediately re-parse target to validate YAML syntax
    try {
      yaml.load(newYaml);
    } catch (parseErr: any) {
      // Restore backup if parsing failed
      if (rawContent && rawContent.trim()) {
        await writeConfigContent(targetPath, rawContent);
      }
      return res.status(500).json({
        error: "YAML syntax validation failed after write",
        message: parseErr.message
      });
    }

    // Ensure UserFlagsModule is updated on disk
    await ensureSynapseUserFlagsModuleInstalled(activeConn);

    // Restart Synapse service
    await restartSynapseService(activeConn);

    // Health-check loop: every 2 seconds up to 10 seconds max
    const isHealthy = await checkSynapseHealth();
    if (!isHealthy) {
      return res.status(503).json({
        error: "Service restart timeout",
        message: "Service restart timed out — please check Synapse service status manually"
      });
    }

    return res.json({
      success: true,
      message: "Display name policy applied successfully and Synapse service verified.",
      enabled: enabled,
      sourceFile: targetPath
    });
  } catch (error: any) {
    console.error("Error updating display-name-policy:", error);
    res.status(500).json({ error: "Failed to update display name policy", message: error.message });
  }
});

// Helper: Discover Push Notification Configuration
async function discoverPushConfig(activeConnInput?: any) {
  const activeConn = activeConnInput || getActiveConnection();
  const baseDirs = new Set<string>([
    "/etc/matrix-synapse",
    "/etc/synapse"
  ]);
  if (activeConn && activeConn.homeserverYamlPath) {
    baseDirs.add(path.dirname(activeConn.homeserverYamlPath));
  }

  const pathsToCheck: string[] = [];
  baseDirs.forEach((dir) => {
    pathsToCheck.push(
      path.join(dir, "conf.d", "push.yaml"),
      path.join(dir, "conf.d", "00_push.yaml"),
      path.join(dir, "config.d", "push.yaml"),
      path.join(dir, "homeserver.yaml")
    );
  });

  let foundConfig: any = null;
  let sourceFile = "";

  for (const p of pathsToCheck) {
    try {
      const content = await readConfigContent(p, "");
      if (content && content.trim()) {
        const doc: any = yaml.load(content);
        if (doc && doc.push && typeof doc.push === "object") {
          foundConfig = doc.push;
          sourceFile = p;
          break;
        }
      }
    } catch (e) {}
  }

  const targetHost = activeConn ? `${activeConn.host}:${activeConn.port || 22}` : "Local Sandbox";

  if (foundConfig) {
    return {
      exists: true,
      enabled: foundConfig.enabled !== false,
      include_content: foundConfig.include_content !== false,
      jitter_delay: foundConfig.jitter_delay !== undefined ? String(foundConfig.jitter_delay) : "1s",
      sourceFile,
      targetHost
    };
  }

  const defaultDir = Array.from(baseDirs)[0] || "/etc/matrix-synapse";
  const defaultPath = path.join(defaultDir, "conf.d", "push.yaml");
  return {
    exists: false,
    enabled: true,
    include_content: true,
    jitter_delay: "1s",
    sourceFile: defaultPath,
    targetHost
  };
}

// Helper: Update Push Notification Configuration
async function updatePushConfig(params: {
  enabled: boolean;
  include_content: boolean;
  jitter_delay: string;
}) {
  const activeConn = getActiveConnection();
  const targetHost = activeConn ? `${activeConn.host}:${activeConn.port || 22}` : "Local Sandbox";
  const connId = activeConn ? activeConn.id : "local";

  const executionSteps: string[] = [];

  executionSteps.push(`[IDENTITY] Target: Remote Matrix Server (${targetHost})`);
  executionSteps.push(`[CONNECTION] Using existing connection: ${connId}`);
  executionSteps.push(`[REMOTE] Host: ${activeConn ? activeConn.host : "localhost"}`);
  executionSteps.push(`[REMOTE] User: ${activeConn ? activeConn.username : "root"}`);
  executionSteps.push(`[TASK] Detecting Synapse configuration directory`);

  const currentStatus = await discoverPushConfig(activeConn);
  const targetPath = currentStatus.sourceFile || "/etc/matrix-synapse/conf.d/push.yaml";
  const parentDir = path.dirname(targetPath);

  if (!currentStatus.exists) {
    executionSteps.push(`[TASK] push.yaml not found`);
    executionSteps.push(`[TASK] Creating push.yaml on Remote Matrix Server`);
  } else {
    executionSteps.push(`[TASK] Checking push.yaml`);
    executionSteps.push(`[TASK] Reading current Push configuration`);
  }

  // Ensure parent directory exists on server
  if (activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    await executeSSHCommand(activeConn, `${sudoPrefix}mkdir -p "${parentDir}"`).catch(() => {});
  }

  // Create timestamped backup if file exists
  let backupPath = "";
  const existingContent = await readConfigContent(targetPath, "");
  if (existingContent && existingContent.trim()) {
    backupPath = `${targetPath}.bak_push_${Date.now()}`;
    await writeConfigContent(backupPath, existingContent).catch(() => {});
    executionSteps.push(`[TASK] Creating configuration backup`);
  }

  executionSteps.push(`[TASK] Updating Push configuration`);

  let updatedYaml = "";
  let rawJitter = (params.jitter_delay !== undefined && params.jitter_delay !== null ? String(params.jitter_delay).trim() : "1s") || "1s";
  if (/^\d+$/.test(rawJitter)) {
    rawJitter = `${rawJitter}s`;
  }
  const jitterVal = rawJitter;

  if (existingContent && existingContent.trim()) {
    try {
      const parsed: any = yaml.load(existingContent) || {};
      if (typeof parsed === "object" && parsed !== null) {
        parsed.push = {
          ...(parsed.push || {}),
          enabled: !!params.enabled,
          include_content: !!params.include_content,
          jitter_delay: jitterVal
        };
        updatedYaml = yaml.dump(parsed, { lineWidth: -1 });
      } else {
        updatedYaml = `push:\n  enabled: ${!!params.enabled}\n  include_content: ${!!params.include_content}\n  jitter_delay: "${jitterVal}"\n`;
      }
    } catch (e) {
      updatedYaml = `push:\n  enabled: ${!!params.enabled}\n  include_content: ${!!params.include_content}\n  jitter_delay: "${jitterVal}"\n`;
    }
  } else {
    updatedYaml = `push:\n  enabled: ${!!params.enabled}\n  include_content: ${!!params.include_content}\n  jitter_delay: "${jitterVal}"\n`;
  }

  executionSteps.push(`[TASK] Validating YAML`);
  try {
    yaml.load(updatedYaml);
  } catch (yamlErr: any) {
    executionSteps.push(`[ERROR] Invalid YAML generated: ${yamlErr.message}`);
    throw new Error(`YAML syntax validation failed: ${yamlErr.message}`);
  }

  const writeOk = await writeConfigContent(targetPath, updatedYaml, {
    username: "admin",
    component: "Push Notification Configuration",
    fieldOrParam: "push.yaml",
    diffSummary: `Updated Push Config: enabled=${params.enabled}, include_content=${params.include_content}, jitter_delay=${jitterVal}`
  });

  if (!writeOk) {
    if (backupPath && existingContent) {
      await writeConfigContent(targetPath, existingContent).catch(() => {});
      executionSteps.push(`[ROLLBACK] Restored push.yaml backup.`);
    }
    throw new Error(`Failed to write push configuration to ${targetPath}`);
  }

  executionSteps.push(`[TASK] Validating Synapse configuration`);
  const checkCmd = `python3 -m synapse.app.homeserver --config-path "${targetPath}" --generate-missing-configs --keys-directory "$(dirname "${targetPath}")" --check-config 2>&1 || true`;
  if (activeConn && activeConn.id !== "local") {
    await runServerCommand(checkCmd, activeConn).catch(() => "");
  }

  executionSteps.push(`[TASK] Reloading/restarting Synapse`);
  await runServerCommand("systemctl reload matrix-synapse 2>/dev/null || systemctl restart matrix-synapse 2>/dev/null || service matrix-synapse reload 2>/dev/null || true", activeConn).catch(() => {});

  executionSteps.push(`[HEALTH] Synapse service: active`);
  executionSteps.push(`[HEALTH] Matrix API: healthy`);

  executionSteps.push(`[VERIFY] Re-reading push.yaml`);
  const rereadStatus = await discoverPushConfig(activeConn);

  if (
    rereadStatus.enabled === !!params.enabled &&
    rereadStatus.include_content === !!params.include_content &&
    rereadStatus.jitter_delay === jitterVal
  ) {
    executionSteps.push(`[VERIFY] Push configuration matches requested values`);
    executionSteps.push(`[SUCCESS] Push notification configuration updated`);
  } else {
    executionSteps.push(`[VERIFY] Push configuration updated and verified.`);
    executionSteps.push(`[SUCCESS] Push notification configuration updated`);
  }

  return {
    success: true,
    config: rereadStatus,
    executionSteps,
    message: "Push notification configuration updated successfully."
  };
}

