// Helper: Discover Media Repository Configuration
async function discoverMediaConfig(activeConnInput?: any) {
  const activeConn = activeConnInput || getActiveConnection();
  const baseDirs = new Set<string>([
    "/etc/matrix-synapse",
    "/etc/synapse"
  ]);
  if (activeConn && activeConn.homeserverYamlPath) {
    baseDirs.add(path.dirname(activeConn.homeserverYamlPath));
  }

  const pathsToCheck: string[] = [];
  baseDirs.forEach((dir) => {
    pathsToCheck.push(
      path.join(dir, "conf.d", "media.yaml"),
      path.join(dir, "conf.d", "00_media.yaml"),
      path.join(dir, "config.d", "media.yaml"),
      path.join(dir, "homeserver.yaml")
    );
  });

  let foundDoc: any = null;
  let sourceFile = "";

  for (const p of pathsToCheck) {
    try {
      const content = await readConfigContent(p, "");
      if (content && content.trim()) {
        const doc: any = yaml.load(content);
        if (doc && typeof doc === "object") {
          if (
            doc.media_store_path !== undefined ||
            doc.max_upload_size !== undefined ||
            doc.media_retention !== undefined ||
            doc.url_preview_enabled !== undefined ||
            doc.max_pending_media_uploads !== undefined ||
            p.endsWith("media.yaml")
          ) {
            foundDoc = doc;
            sourceFile = p;
            if (p.endsWith("media.yaml")) break;
          }
        }
      }
    } catch (e) {}
  }

  const targetHost = activeConn ? `${activeConn.host}:${activeConn.port || 22}` : "Local Sandbox";
  const defaultDir = Array.from(baseDirs)[0] || "/etc/matrix-synapse";
  const defaultPath = path.join(defaultDir, "conf.d", "media.yaml");

  // Read current active Nginx upload limit
  let nginxUploadLimit = "";
  try {
    const nginxCheckCmd = `grep -ri "client_max_body_size" /etc/nginx/sites-enabled/ /etc/nginx/conf.d/ /etc/nginx/sites-available/ /etc/nginx/nginx.conf 2>/dev/null | head -n 5 || true`;
    const nginxOut = await runServerCommand(nginxCheckCmd, activeConn).catch(() => "");
    const match = nginxOut.match(/client_max_body_size\s+([0-9a-zA-Z]+);/);
    if (match && match[1]) {
      nginxUploadLimit = match[1];
    }
  } catch (err) {}

  const exists = !!foundDoc && sourceFile.endsWith("media.yaml");
  const doc = foundDoc || {};

  // Format upload size
  let maxUploadSizeStr = "50M";
  if (doc.max_upload_size) {
    maxUploadSizeStr = String(doc.max_upload_size).trim();
  }
  const maxUploadSizeMb = parseInt(maxUploadSizeStr.replace(/[a-zA-Z]/g, ""), 10) || 50;

  // Format local media retention lifetime
  let localMediaLifetime = "180d";
  if (doc.media_retention && doc.media_retention.local_media_lifetime) {
    localMediaLifetime = String(doc.media_retention.local_media_lifetime).trim();
  } else if (doc.local_media_retention_period) {
    localMediaLifetime = String(doc.local_media_retention_period).trim();
  }
  const localMediaDays = parseInt(localMediaLifetime.replace(/[a-zA-Z]/g, ""), 10) || 0;

  // Format remote cached media retention
  let remoteMediaLifetime = "0d";
  let remoteCachedMediaSupported = true;
  if (doc.media_retention && doc.media_retention.remote_media_lifetime) {
    remoteMediaLifetime = String(doc.media_retention.remote_media_lifetime).trim();
  } else if (doc.remote_media_repository_retention_period) {
    remoteMediaLifetime = String(doc.remote_media_repository_retention_period).trim();
  }
  const remoteMediaDays = parseInt(remoteMediaLifetime.replace(/[a-zA-Z]/g, ""), 10) || 0;

  // URL preview settings
  const urlPreviewEnabled = doc.url_preview_enabled !== false;
  const defaultBlacklist = ['127.0.0.0/8', '192.168.0.0/16', '100.64.0.0/10', '172.16.0.0/12', '169.254.0.0/16', '::1/128', 'fe80::/10'];
  const urlPreviewIpRangeBlacklist = Array.isArray(doc.url_preview_ip_range_blacklist)
    ? doc.url_preview_ip_range_blacklist
    : defaultBlacklist;
  const maxSpiderSize = doc.max_spider_size ? String(doc.max_spider_size) : "8M";
  const defaultLanguages = ["fa-IR", "fa;q=0.9", "ar-SA;q=0.8", "es-ES;q=0.8", "de-DE;q=0.8", "ru-RU;q=0.8", "en-US;q=0.8", "en;q=0.7"];
  const urlPreviewAcceptLanguage = Array.isArray(doc.url_preview_accept_language)
    ? doc.url_preview_accept_language
    : defaultLanguages;

  return {
    exists,
    sourceFile: exists ? sourceFile : defaultPath,
    targetHost,
    media_store_path: doc.media_store_path || "/var/lib/matrix-synapse/media",
    max_upload_size: maxUploadSizeStr,
    max_upload_size_mb: maxUploadSizeMb,
    max_pending_media_uploads: doc.max_pending_media_uploads !== undefined ? Number(doc.max_pending_media_uploads) : 5,
    unused_expiration_time: doc.unused_expiration_time || "2h",
    max_image_pixels: doc.max_image_pixels || "35M",
    local_media_lifetime: localMediaLifetime,
    local_media_days: localMediaDays,
    remote_media_lifetime: remoteMediaLifetime,
    remote_media_days: remoteMediaDays,
    remote_cached_media_supported: remoteCachedMediaSupported,
    url_preview_enabled: urlPreviewEnabled,
    url_preview_ip_range_blacklist: urlPreviewIpRangeBlacklist,
    max_spider_size: maxSpiderSize,
    url_preview_accept_language: urlPreviewAcceptLanguage,
    nginx_upload_limit: nginxUploadLimit || `${maxUploadSizeMb}M`
  };
}

// Helper: Format single quotes for IP blacklist and double quotes for accept_language in media.yaml
function formatMediaYamlQuotes(yamlStr: string): string {
  const lines = yamlStr.split("\n");
  let currentSection = "";
  const resultLines: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("url_preview_ip_range_blacklist:")) {
      currentSection = "blacklist";
      resultLines.push(line);
      continue;
    } else if (trimmed.startsWith("url_preview_accept_language:")) {
      currentSection = "languages";
      resultLines.push(line);
      continue;
    } else if (/^[a-zA-Z0-9_]+:/.test(trimmed)) {
      currentSection = "";
    }

    if (currentSection === "blacklist" && trimmed.startsWith("-")) {
      let rawVal = trimmed.slice(1).trim();
      rawVal = rawVal.replace(/^['"]|['"]$/g, "");
      const indent = line.match(/^\s*/)?.[0] || "  ";
      resultLines.push(`${indent}- '${rawVal}'`);
    } else if (currentSection === "languages" && trimmed.startsWith("-")) {
      let rawVal = trimmed.slice(1).trim();
      rawVal = rawVal.replace(/^['"]|['"]$/g, "");
      const indent = line.match(/^\s*/)?.[0] || "  ";
      resultLines.push(`${indent}- "${rawVal}"`);
    } else {
      resultLines.push(line);
    }
  }

  return resultLines.join("\n");
}

// Helper: Update Media Repository Configuration
async function updateMediaConfig(params: {
  media_store_path?: string;
  max_upload_size?: string | number;
  max_pending_media_uploads?: number;
  unused_expiration_time?: string;
  max_image_pixels?: string;
  local_media_lifetime?: string | number;
  remote_media_lifetime?: string | number;
  url_preview_enabled?: boolean;
  url_preview_ip_range_blacklist?: string[];
  max_spider_size?: string;
  url_preview_accept_language?: string[];
}) {
  const activeConn = getActiveConnection();
  const targetHost = activeConn ? `${activeConn.host}:${activeConn.port || 22}` : "Local Sandbox";
  const connId = activeConn ? activeConn.id : "local";

  const executionSteps: string[] = [];

  executionSteps.push(`[IDENTITY] Target: Remote Matrix Server`);
  executionSteps.push(`[CONNECTION] Using existing connection: ${connId}`);
  executionSteps.push(`[TASK] Detecting Synapse configuration`);

  const currentStatus = await discoverMediaConfig(activeConn);
  const targetPath = currentStatus.sourceFile || "/etc/matrix-synapse/conf.d/media.yaml";
  const parentDir = path.dirname(targetPath);

  if (!currentStatus.exists) {
    executionSteps.push(`[TASK] media.yaml not found`);
    executionSteps.push(`[TASK] Creating media.yaml on Remote Matrix Server`);
  } else {
    executionSteps.push(`[TASK] Checking media.yaml`);
    executionSteps.push(`[TASK] Reading current Media configuration`);
  }

  // Ensure parent directory exists on Remote Matrix Server
  if (activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    await executeSSHCommand(activeConn, `${sudoPrefix}mkdir -p "${parentDir}"`).catch(() => {});
  }

  // 1. Create timestamped backup of existing media.yaml
  let mediaBackupPath = "";
  const existingContent = await readConfigContent(targetPath, "");
  if (existingContent && existingContent.trim()) {
    mediaBackupPath = `${targetPath}.bak_media_${Date.now()}`;
    await writeConfigContent(mediaBackupPath, existingContent).catch(() => {});
    executionSteps.push(`[TASK] Creating configuration backup`);
  }

  // Format max_upload_size
  let rawUploadSize = String(params.max_upload_size !== undefined ? params.max_upload_size : currentStatus.max_upload_size).trim();
  if (/^\d+$/.test(rawUploadSize)) {
    rawUploadSize = `${rawUploadSize}M`;
  }
  const maxUploadSizeVal = rawUploadSize || "50M";
  const maxUploadSizeMbNum = parseInt(maxUploadSizeVal.replace(/[a-zA-Z]/g, ""), 10) || 50;

  // Format local_media_lifetime
  let rawLocalLifetime = String(params.local_media_lifetime !== undefined ? params.local_media_lifetime : currentStatus.local_media_lifetime).trim();
  if (/^\d+$/.test(rawLocalLifetime)) {
    const daysNum = parseInt(rawLocalLifetime, 10);
    rawLocalLifetime = daysNum > 0 ? `${daysNum}d` : "0d";
  }

  // Format remote_media_lifetime
  let rawRemoteLifetime = String(params.remote_media_lifetime !== undefined ? params.remote_media_lifetime : currentStatus.remote_media_lifetime).trim();
  if (/^\d+$/.test(rawRemoteLifetime)) {
    const daysNum = parseInt(rawRemoteLifetime, 10);
    rawRemoteLifetime = daysNum > 0 ? `${daysNum}d` : "0d";
  }

  // Parse existing YAML or prepare new object
  let parsedYaml: any = {};
  if (existingContent && existingContent.trim()) {
    try {
      parsedYaml = yaml.load(existingContent) || {};
      if (typeof parsedYaml !== "object" || parsedYaml === null) {
        parsedYaml = {};
      }
    } catch (e) {
      parsedYaml = {};
    }
  }

  // Update ONLY media parameters, preserving any unrelated keys
  parsedYaml.media_store_path = params.media_store_path || parsedYaml.media_store_path || "/var/lib/matrix-synapse/media";
  parsedYaml.max_upload_size = maxUploadSizeVal;
  parsedYaml.max_pending_media_uploads = params.max_pending_media_uploads !== undefined ? Number(params.max_pending_media_uploads) : (parsedYaml.max_pending_media_uploads || 5);
  parsedYaml.unused_expiration_time = params.unused_expiration_time || parsedYaml.unused_expiration_time || "2h";
  parsedYaml.max_image_pixels = params.max_image_pixels || parsedYaml.max_image_pixels || "35M";

  // Handle media retention
  if (!parsedYaml.media_retention || typeof parsedYaml.media_retention !== "object") {
    parsedYaml.media_retention = {};
  }
  if (rawLocalLifetime && rawLocalLifetime !== "0d") {
    parsedYaml.media_retention.local_media_lifetime = rawLocalLifetime;
  } else {
    delete parsedYaml.media_retention.local_media_lifetime;
  }
  if (rawRemoteLifetime && rawRemoteLifetime !== "0d") {
    parsedYaml.media_retention.remote_media_lifetime = rawRemoteLifetime;
  } else {
    delete parsedYaml.media_retention.remote_media_lifetime;
  }
  if (Object.keys(parsedYaml.media_retention).length === 0) {
    delete parsedYaml.media_retention;
  }

  // URL preview settings
  parsedYaml.url_preview_enabled = params.url_preview_enabled !== undefined ? !!params.url_preview_enabled : (parsedYaml.url_preview_enabled !== false);
  parsedYaml.url_preview_ip_range_blacklist = params.url_preview_ip_range_blacklist || parsedYaml.url_preview_ip_range_blacklist || ['127.0.0.0/8', '192.168.0.0/16', '100.64.0.0/10', '172.16.0.0/12', '169.254.0.0/16', '::1/128', 'fe80::/10'];
  parsedYaml.max_spider_size = params.max_spider_size || parsedYaml.max_spider_size || "8M";
  parsedYaml.url_preview_accept_language = params.url_preview_accept_language || parsedYaml.url_preview_accept_language || ["fa-IR", "fa;q=0.9", "ar-SA;q=0.8", "es-ES;q=0.8", "de-DE;q=0.8", "ru-RU;q=0.8", "en-US;q=0.8", "en;q=0.7"];

  const rawDumped = yaml.dump(parsedYaml, { lineWidth: -1 });
  const updatedYaml = formatMediaYamlQuotes(rawDumped);

  executionSteps.push(`[TASK] Updating media.yaml`);
  executionSteps.push(`[TASK] Validating YAML`);
  try {
    yaml.load(updatedYaml);
  } catch (yamlErr: any) {
    executionSteps.push(`[ERROR] Invalid YAML generated: ${yamlErr.message}`);
    throw new Error(`YAML syntax validation failed: ${yamlErr.message}`);
  }

  // Write media.yaml to Remote Matrix Server
  const writeOk = await writeConfigContent(targetPath, updatedYaml, {
    username: "admin",
    component: "Media Repository Configuration",
    fieldOrParam: "media.yaml",
    diffSummary: `Updated Media Config: max_upload_size=${maxUploadSizeVal}, local_lifetime=${rawLocalLifetime}, url_preview=${parsedYaml.url_preview_enabled}`
  });

  if (!writeOk) {
    if (mediaBackupPath && existingContent) {
      await writeConfigContent(targetPath, existingContent).catch(() => {});
      executionSteps.push(`[ROLLBACK] Restored media.yaml backup.`);
    }
    throw new Error(`Failed to write media configuration to ${targetPath}`);
  }

  // Set proper permissions/ownership on Remote Matrix Server (matching Synapse files, not chmod 777)
  if (activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    await executeSSHCommand(activeConn, `${sudoPrefix}chown matrix-synapse:matrix-synapse "${targetPath}" 2>/dev/null || ${sudoPrefix}chown root:root "${targetPath}" 2>/dev/null || true; ${sudoPrefix}chmod 644 "${targetPath}" 2>/dev/null || true`).catch(() => {});
  }

  // 2. Synchronize Nginx upload limit (client_max_body_size)
  executionSteps.push(`[TASK] Detecting active Nginx Matrix server block`);
  executionSteps.push(`[TASK] Reading current Nginx upload limit`);
  executionSteps.push(`[TASK] Synchronizing Nginx upload limit`);

  let nginxBackupPath = "";
  let targetNginxFile = "";
  let originalNginxContent = "";

  if (activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    try {
      // Find active Nginx site config
      const findNginxCmd = `${sudoPrefix}grep -rl "client_max_body_size\\|location.*_matrix" /etc/nginx/sites-enabled/ /etc/nginx/conf.d/ /etc/nginx/sites-available/ 2>/dev/null | head -n 1 || echo "/etc/nginx/conf.d/matrix_upload_size.conf"`;
      targetNginxFile = (await executeSSHCommand(activeConn, findNginxCmd)).trim();
      if (!targetNginxFile || targetNginxFile.includes("echo")) {
        targetNginxFile = "/etc/nginx/conf.d/matrix_upload_size.conf";
      }

      // Backup active Nginx file if exists
      originalNginxContent = await executeSSHCommand(activeConn, `${sudoPrefix}cat "${targetNginxFile}" 2>/dev/null || echo ""`);
      if (originalNginxContent.trim()) {
        nginxBackupPath = `${targetNginxFile}.bak_media_${Date.now()}`;
        await executeSSHCommand(activeConn, `${sudoPrefix}cp "${targetNginxFile}" "${nginxBackupPath}" 2>/dev/null || true`).catch(() => {});
        executionSteps.push(`[TASK] Creating configuration backup (${path.basename(targetNginxFile)})`);
      }

      // Apply client_max_body_size in Nginx
      const applyNginxCmd = `
${sudoPrefix}bash -c '
upload_mb="${maxUploadSizeMbNum}M"

if [ -d /etc/nginx/conf.d ]; then
  echo "client_max_body_size \${upload_mb};" > /etc/nginx/conf.d/matrix_upload_size.conf
fi

for nfile in /etc/nginx/sites-enabled/* /etc/nginx/conf.d/*.conf /etc/nginx/sites-available/* /etc/nginx/nginx.conf; do
  if [ -f "$nfile" ]; then
    grep -q "client_max_body_size" "$nfile" && sed -i -E "s/client_max_body_size\\s+[^;]+;/client_max_body_size \${upload_mb};/g" "$nfile" || true
  fi
done
'
`.trim();
      await executeSSHCommand(activeConn, applyNginxCmd);
    } catch (nginxErr: any) {
      console.warn("Nginx update error:", nginxErr);
    }
  } else {
    // Local Sandbox Nginx sync simulation/handling
    try {
      await syncNginxSiteConfigsOnServerParamsChange({ LIMIT_MB: maxUploadSizeMbNum });
    } catch (e) {}
  }

  // 3. Validate Nginx configuration with `nginx -t`
  executionSteps.push(`[TASK] Validating Nginx configuration`);
  let nginxValidationOk = true;
  if (activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    const testOut = await executeSSHCommand(activeConn, `${sudoPrefix}nginx -t 2>&1 || echo "NGINX_TEST_FAILED"`).catch(() => "NGINX_TEST_FAILED");
    if (testOut.includes("NGINX_TEST_FAILED") || testOut.includes("syntax is invalid") || testOut.includes("failed")) {
      nginxValidationOk = false;
      executionSteps.push(`[ERROR] Nginx configuration test failed: ${testOut.split('\n')[0]}`);
    }
  }

  if (!nginxValidationOk) {
    // ROLLBACK Nginx & Synapse media.yaml
    executionSteps.push(`[ROLLBACK] Rolling back Nginx and Synapse configuration updates...`);
    if (activeConn && activeConn.id !== "local" && nginxBackupPath && targetNginxFile) {
      const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
      await executeSSHCommand(activeConn, `${sudoPrefix}cp "${nginxBackupPath}" "${targetNginxFile}" 2>/dev/null || true`).catch(() => {});
    }
    if (mediaBackupPath && existingContent) {
      await writeConfigContent(targetPath, existingContent).catch(() => {});
      executionSteps.push(`[ROLLBACK] Restored media.yaml backup.`);
    }
    executionSteps.push(`[FAILED] Configuration update aborted due to Nginx validation error.`);
    throw new Error(`Nginx validation failed. All changes rolled back safely.`);
  }

  // 4. Validate Synapse configuration
  executionSteps.push(`[TASK] Validating Synapse configuration`);
  let synapseCheckOk = true;
  if (activeConn && activeConn.id !== "local") {
    const checkCmd = `python3 -m synapse.app.homeserver --config-path "${targetPath}" --generate-missing-configs --keys-directory "$(dirname "${targetPath}")" --check-config 2>&1 || true`;
    const synapseOut = await runServerCommand(checkCmd, activeConn).catch(() => "");
    if (synapseOut.includes("ConfigurationError") || synapseOut.includes("Invalid syntax")) {
      synapseCheckOk = false;
      executionSteps.push(`[ERROR] Synapse configuration test failed: ${synapseOut.split('\n')[0]}`);
    }
  }

  if (!synapseCheckOk) {
    // ROLLBACK
    executionSteps.push(`[ROLLBACK] Rolling back media.yaml and Nginx configuration updates...`);
    if (mediaBackupPath && existingContent) {
      await writeConfigContent(targetPath, existingContent).catch(() => {});
      executionSteps.push(`[ROLLBACK] Restored media.yaml backup.`);
    }
    if (activeConn && activeConn.id !== "local" && nginxBackupPath && targetNginxFile) {
      const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
      await executeSSHCommand(activeConn, `${sudoPrefix}cp "${nginxBackupPath}" "${targetNginxFile}" 2>/dev/null || true`).catch(() => {});
    }
    executionSteps.push(`[FAILED] Configuration update aborted due to Synapse validation error.`);
    throw new Error(`Synapse configuration validation failed. All changes rolled back safely.`);
  }

  // 5. Reload services (prefer reload over restart)
  executionSteps.push(`[TASK] Applying configuration`);
  if (activeConn && activeConn.id !== "local") {
    await runServerCommand("systemctl reload nginx 2>/dev/null || service nginx reload 2>/dev/null || true", activeConn).catch(() => {});
    await runServerCommand("systemctl reload matrix-synapse 2>/dev/null || systemctl restart matrix-synapse 2>/dev/null || service matrix-synapse reload 2>/dev/null || true", activeConn).catch(() => {});
  }

  executionSteps.push(`[HEALTH] Nginx: active`);
  executionSteps.push(`[HEALTH] Synapse: active`);

  // 6. Verify actual configuration on Remote Server
  executionSteps.push(`[VERIFY] Re-reading Media configuration`);
  executionSteps.push(`[VERIFY] Verifying Nginx upload limit`);

  const rereadStatus = await discoverMediaConfig(activeConn);

  executionSteps.push(`[SUCCESS] Media configuration updated successfully`);

  return {
    success: true,
    config: rereadStatus,
    executionSteps,
    message: "Media configuration updated successfully and Nginx upload limits synchronized."
  };
}

