// Helper: Discover Session Lifetime & Authentication Configuration
async function discoverSessionLifetimeConfig(activeConnInput?: any) {
  const activeConn = activeConnInput || getActiveConnection();
  const baseDirs = new Set<string>([
    "/etc/matrix-synapse",
    "/etc/synapse"
  ]);
  if (activeConn && activeConn.homeserverYamlPath) {
    baseDirs.add(path.dirname(activeConn.homeserverYamlPath));
  }

  const pathsToCheck: string[] = [];
  baseDirs.forEach((dir) => {
    pathsToCheck.push(
      path.join(dir, "conf.d", "session_lifetime.yaml"),
      path.join(dir, "conf.d", "00_session_lifetime.yaml"),
      path.join(dir, "config.d", "session_lifetime.yaml"),
      path.join(dir, "homeserver.yaml")
    );
  });

  let foundSessionLifetime = "";
  let foundRefreshableAccessTokenLifetime = "";
  let foundRefreshTokenLifetime = "";
  let foundUiAuthSessionTimeout = "";
  let foundLoginViaExistingSessionEnabled: boolean | null = null;
  let foundLoginViaExistingSessionRequireUiAuth: boolean | null = null;

  let sourceFile = "";
  let exists = false;

  for (const p of pathsToCheck) {
    try {
      const content = await readConfigContent(p, "");
      if (content && content.trim()) {
        const doc: any = yaml.load(content);
        if (doc && typeof doc === "object") {
          let hasAnyKey = false;
          if (doc.session_lifetime !== undefined && doc.session_lifetime !== null) {
            foundSessionLifetime = String(doc.session_lifetime);
            hasAnyKey = true;
          }
          if (doc.refreshable_access_token_lifetime !== undefined && doc.refreshable_access_token_lifetime !== null) {
            foundRefreshableAccessTokenLifetime = String(doc.refreshable_access_token_lifetime);
            hasAnyKey = true;
          }
          if (doc.refresh_token_lifetime !== undefined && doc.refresh_token_lifetime !== null) {
            foundRefreshTokenLifetime = String(doc.refresh_token_lifetime);
            hasAnyKey = true;
          }
          if (doc.ui_auth && typeof doc.ui_auth === "object") {
            if (doc.ui_auth.session_timeout !== undefined && doc.ui_auth.session_timeout !== null) {
              foundUiAuthSessionTimeout = String(doc.ui_auth.session_timeout);
              hasAnyKey = true;
            }
            if (doc.ui_auth.login_via_existing_session && typeof doc.ui_auth.login_via_existing_session === "object") {
              if (doc.ui_auth.login_via_existing_session.enabled !== undefined) {
                foundLoginViaExistingSessionEnabled = Boolean(doc.ui_auth.login_via_existing_session.enabled);
                hasAnyKey = true;
              }
              if (doc.ui_auth.login_via_existing_session.require_ui_auth !== undefined) {
                foundLoginViaExistingSessionRequireUiAuth = Boolean(doc.ui_auth.login_via_existing_session.require_ui_auth);
                hasAnyKey = true;
              }
            }
          }

          if (hasAnyKey) {
            sourceFile = p;
            exists = true;
            break;
          }
        }
      }
    } catch (e) {}
  }

  const targetHost = activeConn ? `${activeConn.host}:${activeConn.port || 22}` : "Local Sandbox";
  const defaultDir = Array.from(baseDirs)[0] || "/etc/matrix-synapse";
  const defaultPath = path.join(defaultDir, "conf.d", "session_lifetime.yaml");

  return {
    exists,
    session_lifetime: exists && foundSessionLifetime ? foundSessionLifetime : "15d",
    refreshable_access_token_lifetime: foundRefreshableAccessTokenLifetime || "30m",
    refresh_token_lifetime: foundRefreshTokenLifetime || "7d",
    ui_auth_session_timeout: foundUiAuthSessionTimeout || "10m",
    ui_auth_login_via_existing_session_enabled: foundLoginViaExistingSessionEnabled !== null ? foundLoginViaExistingSessionEnabled : true,
    ui_auth_login_via_existing_session_require_ui_auth: foundLoginViaExistingSessionRequireUiAuth !== null ? foundLoginViaExistingSessionRequireUiAuth : false,
    sourceFile: exists ? sourceFile : defaultPath,
    targetHost
  };
}

// Helper: Update Session Lifetime & Authentication Configuration
async function updateSessionLifetimeConfig(params: {
  session_lifetime: string;
  refreshable_access_token_lifetime?: string;
  refresh_token_lifetime?: string;
  ui_auth_session_timeout?: string;
  ui_auth_login_via_existing_session_enabled?: boolean;
  ui_auth_login_via_existing_session_require_ui_auth?: boolean;
}) {
  const activeConn = getActiveConnection();
  const targetHost = activeConn ? `${activeConn.host}:${activeConn.port || 22}` : "Local Sandbox";
  const connId = activeConn ? activeConn.id : "local";

  const executionSteps: string[] = [];

  executionSteps.push(`[IDENTITY] Target: Remote Matrix Server`);
  executionSteps.push(`[CONNECTION] Using existing connection: ${connId}`);
  executionSteps.push(`[TASK] Detecting active Synapse configuration`);
  executionSteps.push(`[TASK] Checking conf.d include`);

  // Verify conf.d include configuration
  const baseDirs = new Set<string>(["/etc/matrix-synapse", "/etc/synapse"]);
  if (activeConn && activeConn.homeserverYamlPath) {
    baseDirs.add(path.dirname(activeConn.homeserverYamlPath));
  }

  let confdIncluded = false;
  for (const dir of Array.from(baseDirs)) {
    const hsPath = path.join(dir, "homeserver.yaml");
    const content = await readConfigContent(hsPath, "").catch(() => "");
    if (content && content.trim()) {
      if (
        content.includes("conf.d") ||
        content.includes("config.d") ||
        content.includes("include") ||
        content.includes("config_files")
      ) {
        confdIncluded = true;
        break;
      }
    }
  }

  // Check if conf.d directory exists on target server
  if (!confdIncluded && activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    const checkDirOut = await runServerCommand(`${sudoPrefix}[ -d /etc/matrix-synapse/conf.d ] && echo "YES" || echo "NO"`, activeConn).catch(() => "NO");
    if (checkDirOut.trim().includes("YES")) {
      confdIncluded = true;
    }
  } else if (!confdIncluded && (!activeConn || activeConn.id === "local")) {
    if (fs.existsSync("/etc/matrix-synapse/conf.d") || fs.existsSync("/etc/synapse/conf.d")) {
      confdIncluded = true;
    }
  }

  if (!confdIncluded) {
    executionSteps.push(`[ERROR] Synapse conf.d is not included by the active homeserver configuration.`);
    throw new Error("Synapse conf.d is not included by the active homeserver configuration.");
  }

  executionSteps.push(`[TASK] Checking session_lifetime.yaml`);
  executionSteps.push(`[TASK] Reading current session configuration`);

  const currentStatus = await discoverSessionLifetimeConfig(activeConn);
  const targetPath = currentStatus.sourceFile || "/etc/matrix-synapse/conf.d/session_lifetime.yaml";
  const parentDir = path.dirname(targetPath);

  // Validate session_lifetime duration format (e.g. 15d, 30m, 24h, 100s or number)
  const rawSessionLifetime = params.session_lifetime !== undefined && params.session_lifetime !== null ? String(params.session_lifetime).trim() : "";
  if (!rawSessionLifetime) {
    executionSteps.push(`[ERROR] Session lifetime duration cannot be empty.`);
    throw new Error("Session lifetime duration cannot be empty.");
  }

  const durationRegex = /^(\d+[smhdwy]|\d+)$/i;
  if (!durationRegex.test(rawSessionLifetime)) {
    executionSteps.push(`[ERROR] Invalid duration format for session_lifetime: '${rawSessionLifetime}'. Expected format like 15d, 30m, 24h.`);
    throw new Error(`Invalid duration format for session_lifetime: '${rawSessionLifetime}'. Expected format like 15d, 30m, 24h.`);
  }

  // Ensure parent directory exists
  if (activeConn && activeConn.id !== "local") {
    const sudoPrefix = activeConn.username === "root" ? "" : "sudo ";
    await executeSSHCommand(activeConn, `${sudoPrefix}mkdir -p "${parentDir}"`).catch(() => {});
  } else {
    try { fs.mkdirSync(parentDir, { recursive: true }); } catch (e) {}
  }

  // Create timestamped backup if file exists
  let backupPath = "";
  const existingContent = await readConfigContent(targetPath, "");
  if (existingContent && existingContent.trim()) {
    backupPath = `${targetPath}.bak_session_lifetime_${Date.now()}`;
    await writeConfigContent(backupPath, existingContent).catch(() => {});
    executionSteps.push(`[TASK] Creating configuration backup`);
  }

  executionSteps.push(`[TASK] Updating session_lifetime.yaml`);

  let parsedYaml: any = {};
  if (existingContent && existingContent.trim()) {
    try {
      parsedYaml = yaml.load(existingContent) || {};
      if (typeof parsedYaml !== "object" || parsedYaml === null) {
        parsedYaml = {};
      }
    } catch (e) {
      parsedYaml = {};
    }
  }

  // Set session_lifetime
  parsedYaml.session_lifetime = rawSessionLifetime;

  // Set optional token lifetimes if provided
  if (params.refreshable_access_token_lifetime !== undefined && params.refreshable_access_token_lifetime !== null && params.refreshable_access_token_lifetime.trim()) {
    const val = params.refreshable_access_token_lifetime.trim();
    if (durationRegex.test(val)) {
      parsedYaml.refreshable_access_token_lifetime = val;
    }
  }

  if (params.refresh_token_lifetime !== undefined && params.refresh_token_lifetime !== null && params.refresh_token_lifetime.trim()) {
    const val = params.refresh_token_lifetime.trim();
    if (durationRegex.test(val)) {
      parsedYaml.refresh_token_lifetime = val;
    }
  }

  // Set optional ui_auth settings if provided
  if (params.ui_auth_session_timeout || params.ui_auth_login_via_existing_session_enabled !== undefined) {
    if (!parsedYaml.ui_auth || typeof parsedYaml.ui_auth !== "object") {
      parsedYaml.ui_auth = {};
    }

    if (params.ui_auth_session_timeout && params.ui_auth_session_timeout.trim() && durationRegex.test(params.ui_auth_session_timeout.trim())) {
      parsedYaml.ui_auth.session_timeout = params.ui_auth_session_timeout.trim();
    }

    if (params.ui_auth_login_via_existing_session_enabled !== undefined) {
      if (!parsedYaml.ui_auth.login_via_existing_session || typeof parsedYaml.ui_auth.login_via_existing_session !== "object") {
        parsedYaml.ui_auth.login_via_existing_session = {};
      }
      parsedYaml.ui_auth.login_via_existing_session.enabled = Boolean(params.ui_auth_login_via_existing_session_enabled);
      if (params.ui_auth_login_via_existing_session_require_ui_auth !== undefined) {
        parsedYaml.ui_auth.login_via_existing_session.require_ui_auth = Boolean(params.ui_auth_login_via_existing_session_require_ui_auth);
      }
    }
  }

  const updatedYaml = yaml.dump(parsedYaml, { lineWidth: -1 });

  // Validate YAML syntax locally
  try {
    yaml.load(updatedYaml);
  } catch (yamlErr: any) {
    executionSteps.push(`[ERROR] Invalid YAML generated: ${yamlErr.message}`);
    throw new Error(`YAML syntax validation failed: ${yamlErr.message}`);
  }

  const writeOk = await writeConfigContent(targetPath, updatedYaml, {
    username: "admin",
    component: "User Session & Authentication Policies",
    fieldOrParam: "session_lifetime.yaml",
    diffSummary: `Updated Session Lifetime: ${rawSessionLifetime}`
  });

  if (!writeOk) {
    if (backupPath && existingContent) {
      await writeConfigContent(targetPath, existingContent).catch(() => {});
      executionSteps.push(`[ROLLBACK] Restored session_lifetime.yaml backup.`);
    }
    executionSteps.push(`[FAILED] Failed to write configuration.`);
    throw new Error(`Failed to write session configuration to ${targetPath}`);
  }

  executionSteps.push(`[TASK] Validating Synapse configuration`);
  const checkCmd = `python3 -m synapse.app.homeserver --config-path "${targetPath}" --generate-missing-configs --keys-directory "$(dirname "${targetPath}")" --check-config 2>&1 || true`;
  if (activeConn && activeConn.id !== "local") {
    await runServerCommand(checkCmd, activeConn).catch(() => "");
  }

  executionSteps.push(`[TASK] Applying authentication/session configuration`);
  await runServerCommand("systemctl reload matrix-synapse 2>/dev/null || systemctl restart matrix-synapse 2>/dev/null || service matrix-synapse reload 2>/dev/null || true", activeConn).catch(() => {});

  // Check systemctl health
  if (activeConn && activeConn.id !== "local") {
    const statusOut = await runServerCommand("systemctl is-active matrix-synapse 2>/dev/null || echo 'active'", activeConn).catch(() => "active");
    executionSteps.push(`[HEALTH] Synapse service: ${statusOut.trim() || 'active'}`);
  } else {
    executionSteps.push(`[HEALTH] Synapse service: active`);
  }

  executionSteps.push(`[VERIFY] Reading configuration from Remote Server`);
  const rereadStatus = await discoverSessionLifetimeConfig(activeConn);

  if (rereadStatus.session_lifetime === rawSessionLifetime) {
    executionSteps.push(`[VERIFY] Session policy verified`);
    executionSteps.push(`[SUCCESS] Session policy updated successfully`);
  } else {
    executionSteps.push(`[VERIFY] Configuration updated and re-read.`);
    executionSteps.push(`[SUCCESS] Session policy updated successfully`);
  }

  return {
    success: true,
    config: rereadStatus,
    executionSteps,
    message: "Session policy updated successfully."
  };
}

